package db

import (
	"context"
	"database/sql"
	"fmt"
	"os"
	"time"

	_ "github.com/jackc/pgx/v5/stdlib"
	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type DB struct {
	SQL   *sql.DB
	Mongo *mongo.Client
	MDB   *mongo.Database
}

func Connect(databaseURL, mongoURI, mongoDB string) (*DB, error) {
	sqlDB, err := sql.Open("pgx", databaseURL)
	if err != nil {
		return nil, fmt.Errorf("open postgres: %w", err)
	}
	sqlDB.SetMaxOpenConns(20)
	sqlDB.SetMaxIdleConns(5)
	sqlDB.SetConnMaxLifetime(time.Hour)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := sqlDB.PingContext(ctx); err != nil {
		return nil, fmt.Errorf("ping postgres: %w", err)
	}

	mctx, mcancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer mcancel()
	mc, err := mongo.Connect(mctx, options.Client().ApplyURI(mongoURI))
	if err != nil {
		return nil, fmt.Errorf("connect mongo: %w", err)
	}
	if err := mc.Ping(mctx, nil); err != nil {
		return nil, fmt.Errorf("ping mongo: %w", err)
	}

	return &DB{SQL: sqlDB, Mongo: mc, MDB: mc.Database(mongoDB)}, nil
}

func (d *DB) Close() {
	if d.SQL != nil {
		_ = d.SQL.Close()
	}
	if d.Mongo != nil {
		_ = d.Mongo.Disconnect(context.Background())
	}
}

func (d *DB) Migrate(schemaPath string) error {
	b, err := os.ReadFile(schemaPath)
	if err != nil {
		return fmt.Errorf("read schema: %w", err)
	}
	if _, err := d.SQL.Exec(string(b)); err != nil {
		return fmt.Errorf("apply schema: %w", err)
	}
	return d.ensureMongo()
}

func (d *DB) ensureMongo() error {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	collections := []struct {
		name    string
		indexes []mongo.IndexModel
	}{
		{
			name: "audit_entries",
			indexes: []mongo.IndexModel{
				{Keys: bson.D{{Key: "auditId", Value: 1}}, Options: options.Index().SetUnique(true)},
				{Keys: bson.D{{Key: "actorId", Value: 1}}},
				{Keys: bson.D{{Key: "entityType", Value: 1}, {Key: "entityId", Value: 1}}},
				{Keys: bson.D{{Key: "action", Value: 1}}},
				{Keys: bson.D{{Key: "occurredAt", Value: -1}}},
				{Keys: bson.D{{Key: "role", Value: 1}}},
			},
		},
		{
			name: "event_log",
			indexes: []mongo.IndexModel{
				{Keys: bson.D{{Key: "seq", Value: 1}}, Options: options.Index().SetUnique(true)},
				{Keys: bson.D{{Key: "createdAt", Value: -1}}},
			},
		},
		{
			name: "serviceability_history",
			indexes: []mongo.IndexModel{
				{Keys: bson.D{{Key: "version", Value: 1}}, Options: options.Index().SetUnique(true)},
			},
		},
	}

	existing, err := d.MDB.ListCollectionNames(ctx, bson.M{})
	if err != nil {
		return err
	}
	have := map[string]bool{}
	for _, n := range existing {
		have[n] = true
	}

	for _, c := range collections {
		if !have[c.name] {
			if err := d.MDB.CreateCollection(ctx, c.name); err != nil {
				// ignore if already exists
				_ = err
			}
		}
		if len(c.indexes) > 0 {
			_, err := d.MDB.Collection(c.name).Indexes().CreateMany(ctx, c.indexes)
			if err != nil {
				return fmt.Errorf("mongo indexes %s: %w", c.name, err)
			}
		}
	}
	// touch empty docs to materialize
	for _, c := range collections {
		count, _ := d.MDB.Collection(c.name).CountDocuments(ctx, bson.M{})
		if count == 0 {
			_, _ = d.MDB.Collection(c.name).InsertOne(ctx, bson.M{"_bootstrap": true, "createdAt": time.Now().UTC()})
			_, _ = d.MDB.Collection(c.name).DeleteMany(ctx, bson.M{"_bootstrap": true})
		}
	}
	return nil
}

func (d *DB) Ready(ctx context.Context) error {
	if err := d.SQL.PingContext(ctx); err != nil {
		return fmt.Errorf("postgres: %w", err)
	}
	if err := d.Mongo.Ping(ctx, nil); err != nil {
		return fmt.Errorf("mongo: %w", err)
	}
	return nil
}

func (d *DB) Reset(schemaPath string) error {
	// Drop and recreate public schema tables
	stmts := []string{
		`DROP SCHEMA public CASCADE`,
		`CREATE SCHEMA public`,
		`GRANT ALL ON SCHEMA public TO PUBLIC`,
	}
	for _, s := range stmts {
		if _, err := d.SQL.Exec(s); err != nil {
			return err
		}
	}
	// Drop mongo collections
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	names, _ := d.MDB.ListCollectionNames(ctx, bson.M{})
	for _, n := range names {
		_ = d.MDB.Collection(n).Drop(ctx)
	}
	return d.Migrate(schemaPath)
}

