func (s *Service) Emit(eventType, entityType, entityID string, audience []string, payload map[string]interface{}) {
	if payload == nil {
		payload = map[string]interface{}{}
	}
	b, _ := json.Marshal(payload)
	ab, _ := json.Marshal(audience)
	var id int64
	_ = s.DB.SQL.QueryRow(`
		INSERT INTO realtime_events (type, entity_type, entity_id, audience_roles, payload)
		VALUES ($1,$2,$3,$4,$5) RETURNING id`, eventType, entityType, entityID, ab, b).Scan(&id)
	s.hub.Broadcast(Event{
		ID: id, Type: eventType, EntityType: entityType, EntityID: entityID,
		Payload: payload, CreatedAt: time.Now().UTC(), Audience: audience,
	})
}

func (s *Service) GetTimeline(sampleID string) []models.TimelineEntry {
	rows, err := s.DB.SQL.Query(`
		SELECT id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
		FROM timeline_events WHERE sample_id=$1::uuid ORDER BY id ASC`, sampleID)
	if err != nil {
		return []models.TimelineEntry{}
	}
	defer rows.Close()
	out := []models.TimelineEntry{}
	for rows.Next() {
		var e models.TimelineEntry
		var details []byte
		var occurred time.Time
		if err := rows.Scan(&e.EventID, &e.Action, &e.ActorID, &e.Role, &e.EntityType, &e.EntityID, &e.Success, &occurred, &details); err != nil {
			continue
		}
		e.OccurredAt = occurred.UTC()
		e.Details = map[string]interface{}{}
		_ = json.Unmarshal(details, &e.Details)
		out = append(out, e)
	}
	return out
}

// ---------- helpers ----------

func contains(ss []string, x string) bool {
	for _, s := range ss {
		if s == x {
			return true
		}
	}
	return false
}

func nullUUID(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

func nullStr(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180
	dLng := (lng2 - lng1) * math.Pi / 180
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*math.Sin(dLng/2)*math.Sin(dLng/2)
	return 2 * R * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
}

func nowUTC() time.Time { return time.Now().UTC() }

func formatTime(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

func scanNullTime(nt sql.NullTime) *time.Time {
	if !nt.Valid {
		return nil
	}
	t := nt.Time.UTC()
	return &t
}

func scanNullStr(ns sql.NullString) *string {
	if !ns.Valid {
		return nil
	}
	s := ns.String
	return &s
}

func scanNullFloat(nf sql.NullFloat64) *float64 {
	if !nf.Valid {
		return nil
	}
	f := nf.Float64
	return &f
}

func isStale(recorded *time.Time, sec int) bool {
	if recorded == nil {
		return true
	}
	return time.Since(*recorded) > time.Duration(sec)*time.Second
}

