	}
	n, _ := res.RowsAffected()
	if n == 0 {
		return nil, Err(404, "not_found", "location not found")
	}
	s.bumpNetwork()
	_ = s.Audit(actorID, role, "location.set_status", "location", id, true, map[string]interface{}{"active": active})
	return map[string]interface{}{"locationId": id, "active": active}, nil
}

func (s *Service) SetLocationFunctionStatus(actorID, role, id, fn string, active bool) (map[string]interface{}, error) {
	col := ""
	switch fn {
	case "collection_point":
		col = "fn_collection_point"
	case "transfer_point":
		col = "fn_transfer_point"
	case "hub":
		col = "fn_hub"
	case "laboratory":
		col = "fn_laboratory"
	default:
		return nil, Err(400, "invalid_location_function", "invalid function")
	}
	res, err := s.DB.SQL.Exec(fmt.Sprintf(`UPDATE locations SET %s=$1, updated_at=NOW() WHERE id=$2::uuid`, col), active, id)
	if err != nil {
		return nil, err
	}
	n, _ := res.RowsAffected()
	if n == 0 {
		return nil, Err(404, "not_found", "location not found")
	}
	s.bumpNetwork()
	loc, err := s.locationResponse(id)
	if err != nil {
		return nil, err
	}
	_ = s.Audit(actorID, role, "location.set_function_status", "location", id, true, map[string]interface{}{"function": fn, "active": active})
	return map[string]interface{}{
		"locationId": id,
		"function":   fn,
		"active":     active,
		"functions":  loc["functions"],
	}, nil
}

func (s *Service) locationResponse(id string) (map[string]interface{}, error) {
	var name string
	var lat, lng, cov float64
	var handling int
	var active, fcp, ftp, fhub, flab bool
	err := s.DB.SQL.QueryRow(`
		SELECT name, latitude, longitude, coverage_km, handling_minutes, active,
			fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory
		FROM locations WHERE id=$1::uuid`, id).
		Scan(&name, &lat, &lng, &cov, &handling, &active, &fcp, &ftp, &fhub, &flab)
	if err == sql.ErrNoRows {
		return nil, Err(404, "not_found", "location not found")
	}
	if err != nil {
		return nil, err
	}
	return map[string]interface{}{
		"locationId":      id,
		"name":            name,
		"coordinate":      models.Coordinate{Latitude: lat, Longitude: lng},
		"coverageKm":      cov,
		"handlingMinutes": handling,
		"active":          active,
		"functions": models.LocationFunctions{
			CollectionPoint: fcp, TransferPoint: ftp, Hub: fhub, Laboratory: flab,
		},
	}, nil
}

// ---------- connections ----------

func (s *Service) CreateConnection(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
	from, _ := req["fromLocationId"].(string)
	to, _ := req["toLocationId"].(string)
	travel := toInt(req["travelMinutes"])
	cost := toFloat(req["costUnits"])
	cooled := toBool(req["cooled"], false)
	active := toBool(req["active"], true)
	if travel < 1 {
		return nil, Err(400, "invalid_json", "travelMinutes must be >=1")
	}
	var id string
	err := s.DB.SQL.QueryRow(`
		INSERT INTO connections (from_location_id, to_location_id, travel_minutes, cost_units, cooled, active)
		VALUES ($1::uuid,$2::uuid,$3,$4,$5,$6) RETURNING id::text`,
		from, to, travel, cost, cooled, active).Scan(&id)
	if err != nil {
		return nil, Err(400, "invalid_json", err.Error())
	}
	s.bumpNetwork()
	_ = s.Audit(actorID, role, "connection.create", "connection", id, true, req)
	return map[string]interface{}{
		"connectionId":   id,
		"fromLocationId": from,
		"toLocationId":   to,
		"travelMinutes":  travel,
		"costUnits":      cost,
		"cooled":         cooled,
		"active":         active,
	}, nil
}

func (s *Service) SetConnectionStatus(actorID, role, id string, active bool) (map[string]interface{}, error) {
	res, err := s.DB.SQL.Exec(`UPDATE connections SET active=$1, updated_at=NOW() WHERE id=$2::uuid`, active, id)
	if err != nil {
		return nil, err
	}
	n, _ := res.RowsAffected()
	if n == 0 {
		return nil, Err(404, "not_found", "connection not found")
	}
	s.bumpNetwork()
	_ = s.Audit(actorID, role, "connection.set_status", "connection", id, true, map[string]interface{}{"active": active})
	return map[string]interface{}{"connectionId": id, "active": active}, nil
}

// ---------- sample types ----------

func (s *Service) CreateSampleType(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
	name, _ := req["name"].(string)
	container, _ := req["containerType"].(string)
	tmin := toFloat(req["temperatureMinC"])
	tmax := toFloat(req["temperatureMaxC"])
	if name == "" || container == "" {
		return nil, Err(400, "invalid_handling_rule", "name and container required")
	}
	if tmin > tmax {
		return nil, Err(400, "invalid_handling_rule", "temperature range invalid")
	}
	qcr := toBool(req["qualifiedCollectorRequired"], true)
	rq, _ := req["requiredQualification"].(string)
	if rq == "" {
		rq = name
	}
	inc := toStringSlice(req["incompatibleSampleTypes"])
	cooled := toBool(req["requiresCooledRoute"], false)
	batch := toBool(req["batchingAllowed"], true)
	if strings.EqualFold(name, "Frost") {
		cooled = true
	}
	if strings.EqualFold(name, "Pulse") {
		batch = false
	}
	incJSON, _ := json.Marshal(inc)
	var id string
	err := s.DB.SQL.QueryRow(`
		INSERT INTO sample_types (name, qualified_collector_required, required_qualification, container_type,
			temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING id::text`,
		name, qcr, rq, container, tmin, tmax, incJSON, cooled, batch).Scan(&id)
	if err != nil {
		if strings.Contains(err.Error(), "duplicate") || strings.Contains(err.Error(), "unique") {
			return nil, Err(409, "concurrent_conflict", "sample type exists")
		}
		return nil, err
	}
	_ = s.Audit(actorID, role, "sample_type.create", "sample_type", id, true, req)
	return s.sampleTypeResponse(id)
}

func (s *Service) UpdateSampleType(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
	id, _ := req["sampleTypeId"].(string)
	container, _ := req["containerType"].(string)
	tmin := toFloat(req["temperatureMinC"])
	tmax := toFloat(req["temperatureMaxC"])
	if tmin > tmax {
		return nil, Err(400, "invalid_handling_rule", "temperature range invalid")
	}
	qcr := toBool(req["qualifiedCollectorRequired"], true)
	rq, _ := req["requiredQualification"].(string)
	inc := toStringSlice(req["incompatibleSampleTypes"])
	cooled := toBool(req["requiresCooledRoute"], false)
	batch := toBool(req["batchingAllowed"], true)
	incJSON, _ := json.Marshal(inc)
	res, err := s.DB.SQL.Exec(`
		UPDATE sample_types SET qualified_collector_required=$1, required_qualification=$2, container_type=$3,
			temperature_min_c=$4, temperature_max_c=$5, incompatible_sample_types=$6,
			requires_cooled_route=$7, batching_allowed=$8, updated_at=NOW()
		WHERE id=$9::uuid`,
		qcr, rq, container, tmin, tmax, incJSON, cooled, batch, id)
	if err != nil {
		return nil, err
	}
	n, _ := res.RowsAffected()
	if n == 0 {
		return nil, Err(404, "not_found", "sample type not found")
	}
	_ = s.Audit(actorID, role, "sample_type.update", "sample_type", id, true, req)
	return s.sampleTypeResponse(id)
}

func (s *Service) sampleTypeResponse(id string) (map[string]interface{}, error) {
	var name, rq, container string
	var qcr, cooled, batch bool
	var tmin, tmax float64
	var inc []byte
	err := s.DB.SQL.QueryRow(`
		SELECT name, qualified_collector_required, required_qualification, container_type,
			temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed
		FROM sample_types WHERE id=$1::uuid`, id).
		Scan(&name, &qcr, &rq, &container, &tmin, &tmax, &inc, &cooled, &batch)
	if err == sql.ErrNoRows {
		return nil, Err(404, "not_found", "sample type not found")
	}
	if err != nil {
		return nil, err
	}
	return map[string]interface{}{
		"sampleTypeId":               id,
		"name":                       name,
		"qualifiedCollectorRequired": qcr,
		"requiredQualification":      rq,
		"containerType":              container,
		"temperatureMinC":            tmin,
		"temperatureMaxC":            tmax,
		"incompatibleSampleTypes":    models.ParseStringSlice(inc),
		"requiresCooledRoute":        cooled,
		"batchingAllowed":            batch,
	}, nil
}

func (s *Service) ConfigureLabAcceptance(actorID, role, labID, typeID string, accepts bool) (map[string]interface{}, error) {
	var id string
	err := s.DB.SQL.QueryRow(`
		INSERT INTO laboratory_acceptance (laboratory_id, sample_type_id, accepts)
		VALUES ($1::uuid,$2::uuid,$3)
		ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts=$3
		RETURNING id::text`, labID, typeID, accepts).Scan(&id)
	if err != nil {
		return nil, err
	}
	s.bumpNetwork()
	_ = s.Audit(actorID, role, "laboratory.configure_acceptance", "laboratory", labID, true,
		map[string]interface{}{"sampleTypeId": typeID, "accepts": accepts})
	return map[string]interface{}{"acceptanceId": id, "accepts": accepts}, nil
}

func (s *Service) ConfigureCapacity(actorID, role, resourceID string, units, cooledUnits int) (map[string]interface{}, error) {
	// try location first
	res, err := s.DB.SQL.Exec(`
		UPDATE locations SET capacity_units=$1, cooled_capacity_units=$2, updated_at=NOW() WHERE id=$3::uuid`,
		units, cooledUnits, resourceID)
	if err != nil {
		return nil, err
	}
	n, _ := res.RowsAffected()
	if n == 0 {
		res, err = s.DB.SQL.Exec(`
			UPDATE connections SET capacity_units=$1, cooled_capacity_units=$2, updated_at=NOW() WHERE id=$3::uuid`,
			units, cooledUnits, resourceID)
		if err != nil {
			return nil, err
		}
		n, _ = res.RowsAffected()
		if n == 0 {
			return nil, Err(404, "not_found", "resource not found")
		}
	}
	s.bumpNetwork()
	_ = s.Audit(actorID, role, "capacity.configure", "capacity", resourceID, true,
		map[string]interface{}{"capacityUnits": units, "cooledCapacityUnits": cooledUnits})
	return map[string]interface{}{
		"resourceId":           resourceID,
		"capacityUnits":        units,
		"cooledCapacityUnits":  cooledUnits,
	}, nil
}

func (s *Service) bumpNetwork() {
	_, _ = s.DB.SQL.Exec(`UPDATE network_meta SET revision = revision + 1 WHERE id=1`)
	go func() { _ = s.rebuildServiceability() }()
}

