func (s *Service) Audit(actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) error {
	if details == nil {
		details = map[string]interface{}{}
	}
	b, _ := json.Marshal(details)
	auditID := uuid.New().String()
	occurred := time.Now().UTC()
	_, err := s.DB.SQL.Exec(`
		INSERT INTO audit_log (audit_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details)
		VALUES ($1::uuid,$2,$3,$4,$5,$6,$7,$8,$9)`,
		auditID, actorID, role, action, entityType, entityID, success, occurred, b)
	if err != nil {
		return err
	}
	// also mongo
	doc := bson.M{
		"auditId": auditID, "audit_id": auditID,
		"actorId": actorID, "actor_id": actorID,
		"role": role, "actorRole": role,
		"action": action,
		"entityType": entityType, "entity_type": entityType,
		"entityId": entityID, "entity_id": entityID,
		"success": success,
		"occurredAt": occurred, "occurred_at": occurred,
		"details": details,
	}
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()
	_, _ = s.DB.MDB.Collection("audit_entries").InsertOne(ctx, doc)
	return nil
}

