package service

import (
	"sync"
	"time"
)

type Event struct {
	ID         int64                  `json:"id"`
	Type       string                 `json:"type"`
	EntityType string                 `json:"entityType"`
	EntityID   string                 `json:"entityId"`
	Payload    map[string]interface{} `json:"payload"`
	CreatedAt  time.Time              `json:"createdAt"`
	Audience   []string               `json:"-"`
}

type subscriber struct {
	ch   chan Event
	role string
}

type EventHub struct {
	mu   sync.RWMutex
	subs map[chan Event]*subscriber
}

func NewEventHub() *EventHub {
	return &EventHub{subs: map[chan Event]*subscriber{}}
}

func (h *EventHub) Subscribe(role string) chan Event {
	ch := make(chan Event, 64)
	h.mu.Lock()
	h.subs[ch] = &subscriber{ch: ch, role: role}
	h.mu.Unlock()
	return ch
}

func (h *EventHub) Unsubscribe(ch chan Event) {
	h.mu.Lock()
	if _, ok := h.subs[ch]; ok {
		delete(h.subs, ch)
		close(ch)
	}
	h.mu.Unlock()
}

func (h *EventHub) Broadcast(ev Event) {
	h.mu.RLock()
	defer h.mu.RUnlock()
	for ch, sub := range h.subs {
		if len(ev.Audience) > 0 {
			ok := false
			for _, a := range ev.Audience {
				if a == sub.role || a == "*" {
					ok = true
					break
				}
			}
			if !ok && sub.role != "administrator" && sub.role != "dispatcher" {
				continue
			}
		}
		select {
		case ch <- ev:
		default:
		}
	}
}

