)

type locRow struct {
	ID               string
	Name             string
	Lat, Lng         float64
	CoverageKm       float64
	HandlingMinutes  int
	Active           bool
	CollectionPoint  bool
	TransferPoint    bool
	Hub              bool
	Laboratory       bool
	CapacityUnits    int
	ReservedUnits    int
	CooledCap        int
	CooledReserved   int
	AcceptedTypes    []string
}

type connRow struct {
	ID             string
	FromID, ToID   string
	TravelMinutes  int
	CostUnits      float64
	Cooled         bool
	Active         bool
