		s.AddTimeline(sampleID, actorID, role, "sample.lab_exception", "sample", sampleID, true, map[string]interface{}{"reason": reason})
		_ = s.Audit(actorID, role, "sample.lab_exception", "sample", sampleID, true, req)
		return 201, map[string]interface{}{"sampleId": sampleID, "status": "exception", "reason": reason}, nil
	})
	if err != nil {
