func (s *Service) createSampleInternal(actorID, role string, req map[string]interface{}, presealed bool) (map[string]interface{}, error) {
	idem, _ := req["idempotencyKey"].(string)
	if idem != "" {
		st, resp, err := s.Idempotent(actorID, idem, "create_collection_request", func() (int, interface{}, error) {
			out, err := s.doCreateSample(actorID, role, req, presealed)
			if err != nil {
				return 0, nil, err
			}
			return 201, out, nil
		})
		if err != nil {
