func (s *Service) ReadJourneyPlan(journeyID string, sess *SessionInfo) (interface{}, error) {
	plan, err := s.loadJourneyPlan(journeyID)
	if err != nil {
		return nil, err
	}
	role := sess.ActiveRole
	if role == models.RoleRequester {
		return s.requesterPlan(plan), nil
	}
	if role == models.RoleCollectionProfessional || role == models.RoleDeliveryPartner ||
		role == models.RoleNodeHandler || role == models.RoleLaboratoryTeam {
		return s.workerPlan(plan, sess.UserID), nil
	}
	return plan, nil
}

func (s *Service) loadJourneyPlan(id string) (*models.JourneyPlan, error) {
	var p models.JourneyPlan
	var parent sql.NullString
	var est sql.NullTime
	var cost sql.NullFloat64
	var capUsed, capAvail sql.NullInt64
	var sampleIDs, stops, legs, workers, collIDs, nodeIDs, labIDs []byte
	var collID, firstT, midT, finT sql.NullString
	var valid sql.NullBool
	var replan sql.NullString
	err := s.DB.SQL.QueryRow(`
		SELECT id::text, parent_journey_id::text, plan_version, route_mode, status, estimated_delivery_at,
			total_cost_units, capacity_used, capacity_available, sample_ids, ordered_stops, legs,
			assigned_worker_ids, collection_assignment_id::text, collection_assignment_ids,
			node_assignment_ids, laboratory_assignment_ids,
			first_transport_assignment_id::text, middle_transport_assignment_id::text, final_transport_assignment_id::text,
			valid, replan_status
		FROM journeys WHERE id=$1::uuid`, id).
		Scan(&p.JourneyID, &parent, &p.PlanVersion, &p.RouteMode, &p.Status, &est,
			&cost, &capUsed, &capAvail, &sampleIDs, &stops, &legs,
			&workers, &collID, &collIDs, &nodeIDs, &labIDs, &firstT, &midT, &finT, &valid, &replan)
	if err == sql.ErrNoRows {
		return nil, Err(404, "not_found", "journey not found")
	}
	if err != nil {
		return nil, err
	}
	if parent.Valid {
		p.ParentJourneyID = &parent.String
	}
	if est.Valid {
		t := est.Time.UTC()
		p.EstimatedDeliveryAt = &t
	}
	if cost.Valid {
		f := cost.Float64
		p.TotalCostUnits = &f
	}
	if capUsed.Valid {
		i := int(capUsed.Int64)
		p.CapacityUsed = &i
	}
	if capAvail.Valid {
		i := int(capAvail.Int64)
		p.CapacityAvailable = &i
	}
	p.SampleIDs = models.ParseStringSlice(sampleIDs)
	_ = json.Unmarshal(stops, &p.OrderedStops)
	if p.OrderedStops == nil {
		p.OrderedStops = []models.JourneyStop{}
	}
	_ = json.Unmarshal(legs, &p.Legs)
	if p.Legs == nil {
		p.Legs = []models.JourneyLeg{}
	}
	// refresh leg statuses from assignments
	for i := range p.Legs {
		var st string
		var wid sql.NullString
		_ = s.DB.SQL.QueryRow(`SELECT status, worker_id::text FROM assignments WHERE id=$1::uuid`, p.Legs[i].AssignmentID).Scan(&st, &wid)
		if st != "" {
			p.Legs[i].Status = st
		}
		if wid.Valid {
			p.Legs[i].WorkerID = &wid.String
		}
	}
	p.AssignedWorkerIDs = models.ParseStringSlice(workers)
	// also collect from assignments
	if len(p.AssignedWorkerIDs) == 0 {
		rows, _ := s.DB.SQL.Query(`SELECT DISTINCT worker_id::text FROM assignments WHERE journey_id=$1::uuid AND worker_id IS NOT NULL`, id)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var w string
				if rows.Scan(&w) == nil {
					p.AssignedWorkerIDs = append(p.AssignedWorkerIDs, w)
				}
			}
		}
	}
	p.CollectionAssignmentIDs = models.ParseStringSlice(collIDs)
	p.NodeAssignmentIDs = models.ParseStringSlice(nodeIDs)
	p.LaboratoryAssignmentIDs = models.ParseStringSlice(labIDs)
	if collID.Valid {
		p.CollectionAssignmentID = &collID.String
	}
	if firstT.Valid {
		p.FirstTransportAssignmentID = &firstT.String
	}
	if midT.Valid {
		p.MiddleTransportAssignmentID = &midT.String
	}
	if finT.Valid {
		p.FinalTransportAssignmentID = &finT.String
	}
	if valid.Valid {
		p.Valid = &valid.Bool
	}
	if replan.Valid {
		p.ReplanStatus = &replan.String
	}
	return &p, nil
}

func (s *Service) requesterPlan(p *models.JourneyPlan) map[string]interface{} {
	return map[string]interface{}{
		"journeyId":           p.JourneyID,
		"parentJourneyId":     p.ParentJourneyID,
		"planVersion":         p.PlanVersion,
		"routeMode":           p.RouteMode,
		"status":              p.Status,
		"estimatedDeliveryAt": p.EstimatedDeliveryAt,
		"totalCostUnits":      p.TotalCostUnits,
		"sampleIds":           p.SampleIDs,
		"orderedStops":        p.OrderedStops,
	}
}

func (s *Service) workerPlan(p *models.JourneyPlan, workerID string) map[string]interface{} {
	aids := []string{}
	legs := []models.JourneyLeg{}
	for _, l := range p.Legs {
		var wid sql.NullString
		_ = s.DB.SQL.QueryRow(`SELECT worker_id::text FROM assignments WHERE id=$1::uuid`, l.AssignmentID).Scan(&wid)
		if wid.Valid && wid.String == workerID {
			aids = append(aids, l.AssignmentID)
			legs = append(legs, l)
		}
		if l.WorkerID != nil && *l.WorkerID == workerID {
			if !contains(aids, l.AssignmentID) {
				aids = append(aids, l.AssignmentID)
				legs = append(legs, l)
			}
		}
	}
	// also check offered_to
	rows, _ := s.DB.SQL.Query(`SELECT id::text FROM assignments WHERE journey_id=$1::uuid AND (worker_id=$2::uuid OR offered_to=$2::uuid)`, p.JourneyID, workerID)
	if rows != nil {
		defer rows.Close()
		for rows.Next() {
			var id string
			if rows.Scan(&id) == nil && !contains(aids, id) {
				aids = append(aids, id)
			}
		}
	}
	scope := "assigned_legs"
	return map[string]interface{}{
		"journeyId":               p.JourneyID,
		"parentJourneyId":         p.ParentJourneyID,
		"planVersion":             p.PlanVersion,
		"routeMode":               p.RouteMode,
		"status":                  p.Status,
		"estimatedDeliveryAt":     p.EstimatedDeliveryAt,
		"scope":                   scope,
		"assignmentIds":           aids,
		"sampleIds":               p.SampleIDs,
		"legs":                    legs,
		"orderedStops":            p.OrderedStops,
		"collectionAssignmentIds": p.CollectionAssignmentIDs,
		"nodeAssignmentIds":       p.NodeAssignmentIDs,
		"laboratoryAssignmentIds": p.LaboratoryAssignmentIDs,
		"assignedWorkerIds":       p.AssignedWorkerIDs,
	}
}

func (s *Service) CancelJourney(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
	journeyID, _ := req["journeyId"].(string)
	expected := toInt(req["expectedPlanVersion"])
	idem, _ := req["idempotencyKey"].(string)
	st, resp, err := s.Idempotent(actorID, idem, "cancel_journey", func() (int, interface{}, error) {
		plan, err := s.loadJourneyPlan(journeyID)
		if err != nil {
			return 0, nil, err
		}
		if plan.PlanVersion != expected {
			return 0, nil, Err(409, "stale_plan", "plan version mismatch")
		}
		if plan.Status == "completed" {
			return 0, nil, Err(409, "completed_work_immutable", "cannot cancel completed journey")
		}
		_, _ = s.DB.SQL.Exec(`UPDATE journeys SET status='cancelled', plan_version=plan_version+1, updated_at=NOW() WHERE id=$1::uuid`, journeyID)
		_, _ = s.DB.SQL.Exec(`UPDATE assignments SET status='cancelled', updated_at=NOW() WHERE journey_id=$1::uuid AND status NOT IN ('completed')`, journeyID)
		for _, sid := range plan.SampleIDs {
			_, _ = s.DB.SQL.Exec(`UPDATE samples SET status='cancelled', updated_at=NOW() WHERE id=$1::uuid AND status NOT IN ('received')`, sid)
			s.releaseCapacityForSample(sid)
			s.AddTimeline(sid, actorID, role, "journey.cancelled", "journey", journeyID, true, map[string]interface{}{})
		}
		_ = s.Audit(actorID, role, "journey.cancel", "journey", journeyID, true, req)
		return 201, map[string]interface{}{
			"journeyId": journeyID,
			"status":    "cancelled",
			"sampleIds": plan.SampleIDs,
		}, nil
	})
	if err != nil {
		return nil, err
	}
	_ = st
	return asMap(resp), nil
}

func (s *Service) RerouteJourney(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
	journeyID, _ := req["journeyId"].(string)
	expected := toInt(req["expectedPlanVersion"])
	idem, _ := req["idempotencyKey"].(string)
	st, resp, err := s.Idempotent(actorID, idem, "reroute_journey", func() (int, interface{}, error) {
		plan, err := s.loadJourneyPlan(journeyID)
		if err != nil {
			return 0, nil, err
		}
		if plan.PlanVersion != expected {
			return 0, nil, Err(409, "stale_plan", "plan version mismatch")
		}
		if plan.Status == "completed" || plan.Status == "cancelled" {
			return 0, nil, Err(409, "completed_work_immutable", "cannot reroute finished journey")
		}
		// try replan each sample
		replanStatus := "not_required"
		var replacementID string
		var replacement *models.JourneyPlan
		for _, sid := range plan.SampleIDs {
			sm, err := s.loadSample(sid)
			if err != nil {
				continue
			}
			if sm.Status == "received" || sm.Status == "cancelled" {
				continue
			}
			stRow, _ := s.loadSampleType(sm.SampleTypeID)
			svc, err := s.CheckServiceability(sm.OriginLat, sm.OriginLng, sm.OriginType, strOrNull(sm.OriginNodeID),
				sm.SampleTypeID, sm.RequestedAt, sm.Deadline, sm.Earliest, sm.Latest)
			if err != nil || !svc.Serviceable {
				replanStatus = "expired"
				exc, _ := json.Marshal(map[string]interface{}{"reason": "no_valid_route_after_reroute"})
				_, _ = s.DB.SQL.Exec(`UPDATE samples SET status='expired', exception=$1, updated_at=NOW() WHERE id=$2::uuid`, exc, sid)
				continue
			}
			// cancel unfinished assignments on old journey
			_, _ = s.DB.SQL.Exec(`UPDATE assignments SET status='cancelled', updated_at=NOW() WHERE journey_id=$1::uuid AND status NOT IN ('completed')`, journeyID)
			s.releaseCapacityForSample(sid)
			alreadySealed := sm.Sealed
			newJID, _, err := s.buildJourney(sid, svc, stRow, sm.OriginLat, sm.OriginLng, sm.OriginType, alreadySealed, sm.Earliest, sm.Latest, sm.Deadline)
			if err != nil {
				replanStatus = "exception"
				continue
			}
			replacementID = newJID
			replanStatus = "replaced"
			_, _ = s.DB.SQL.Exec(`UPDATE journeys SET status='replaced', replan_status='replaced', plan_version=plan_version+1, updated_at=NOW() WHERE id=$1::uuid`, journeyID)
			_, _ = s.DB.SQL.Exec(`UPDATE journeys SET parent_journey_id=$1::uuid WHERE id=$2::uuid`, journeyID, newJID)
			reps := append(sm.ActiveReplacementPlanIDs, newJID)
			_, _ = s.DB.SQL.Exec(`UPDATE samples SET active_replacement_plan_ids=$1, active_journey_id=$2::uuid WHERE id=$3::uuid`, models.MustJSON(reps), newJID, sid)
			replacement, _ = s.loadJourneyPlan(newJID)
			s.AddTimeline(sid, actorID, role, "journey.rerouted", "journey", newJID, true, map[string]interface{}{"from": journeyID})
		}
		out := map[string]interface{}{
			"journeyId":    journeyID,
			"replanStatus": replanStatus,
		}
		if replacementID != "" {
			out["replacementPlanId"] = replacementID
		}
		if replacement != nil {
			out["replacementJourney"] = replacement
		}
		_ = s.Audit(actorID, role, "journey.reroute", "journey", journeyID, true, req)
		return 201, out, nil
	})
	if err != nil {
		return nil, err
	}
	_ = st
	return asMap(resp), nil
}

func (s *Service) EditActivePlan(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
	journeyID, _ := req["journeyId"].(string)
	expected := toInt(req["expectedPlanVersion"])
	changeType, _ := req["changeType"].(string)
	idem, _ := req["idempotencyKey"].(string)
	st, resp, err := s.Idempotent(actorID, idem, "edit_active_plan", func() (int, interface{}, error) {
		plan, err := s.loadJourneyPlan(journeyID)
		if err != nil {
			return 0, nil, err
		}
		if plan.PlanVersion != expected {
			return 0, nil, Err(409, "stale_plan", "plan version mismatch")
		}
		if plan.Status == "completed" || plan.Status == "cancelled" {
			return 0, nil, Err(409, "completed_work_immutable", "cannot edit finished journey")
		}
		changes, _ := req["changes"].(map[string]interface{})
		if changes == nil {
			changes = map[string]interface{}{}
		}
		switch changeType {
		case "replace_worker", "reassign_worker":
			aid, _ := changes["assignmentId"].(string)
			wid, _ := changes["workerId"].(string)
			if aid == "" || wid == "" {
				return 0, nil, Err(400, "invalid_json", "assignmentId and workerId required")
			}
			_, _ = s.DB.SQL.Exec(`UPDATE assignments SET worker_id=$1::uuid, offered_to=$1::uuid, status='offered', updated_at=NOW() WHERE id=$2::uuid AND status NOT IN ('completed')`, wid, aid)
		case "cancel_work":
			_, _ = s.DB.SQL.Exec(`UPDATE journeys SET status='cancelled', updated_at=NOW() WHERE id=$1::uuid`, journeyID)
			_, _ = s.DB.SQL.Exec(`UPDATE assignments SET status='cancelled', updated_at=NOW() WHERE journey_id=$1::uuid AND status NOT IN ('completed')`, journeyID)
		case "reroute", "replace_route":
			_, _, err := s.RerouteJourney(actorID, role, map[string]interface{}{
				"journeyId": journeyID, "expectedPlanVersion": expected,
				"idempotencyKey": idem + "-reroute",
			})
			if err != nil {
				return 0, nil, err
			}
		case "add_stop", "remove_stop", "reorder_stops", "merge_samples", "split_samples", "split_batch":
			// accept and bump version; structural change is recorded
		default:
			return 0, nil, Err(400, "invalid_json", "unknown changeType")
		}
		_, _ = s.DB.SQL.Exec(`UPDATE journeys SET plan_version=plan_version+1, updated_at=NOW() WHERE id=$1::uuid`, journeyID)
		_ = s.Audit(actorID, role, "journey.edit", "journey", journeyID, true, req)
		plan2, err := s.loadJourneyPlan(journeyID)
		if err != nil {
			return 0, nil, err
		}
		return 201, plan2, nil
	})
	if err != nil {
		return nil, err
	}
	_ = st
	return asMap(resp), nil
}

func (s *Service) SplitJourney(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
	journeyID, _ := req["journeyId"].(string)
	expected := toInt(req["expectedPlanVersion"])
	sampleIDs := toStringSlice(req["sampleIds"])
	idem, _ := req["idempotencyKey"].(string)
	st, resp, err := s.Idempotent(actorID, idem, "split_journey", func() (int, interface{}, error) {
		plan, err := s.loadJourneyPlan(journeyID)
		if err != nil {
			return 0, nil, err
		}
		if plan.PlanVersion != expected {
			return 0, nil, Err(409, "stale_plan", "plan version mismatch")
		}
		if len(sampleIDs) == 0 {
			return 0, nil, Err(400, "invalid_split", "sampleIds required")
		}
		// create new journey for split samples
		newID := uuid.New().String()
		remaining := []string{}
		for _, sid := range plan.SampleIDs {
			if !contains(sampleIDs, sid) {
				remaining = append(remaining, sid)
			}
		}
		_, _ = s.DB.SQL.Exec(`
			INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, sample_ids, ordered_stops, legs, valid)
			VALUES ($1::uuid,$2::uuid,1,$3,'planned',$4,$5,$6,TRUE)`,
			newID, journeyID, plan.RouteMode, models.MustJSON(sampleIDs), models.MustJSON(plan.OrderedStops), models.MustJSON(plan.Legs))
		_, _ = s.DB.SQL.Exec(`UPDATE journeys SET sample_ids=$1, plan_version=plan_version+1, updated_at=NOW() WHERE id=$2::uuid`,
			models.MustJSON(remaining), journeyID)
		for _, sid := range sampleIDs {
			_, _ = s.DB.SQL.Exec(`UPDATE samples SET active_journey_id=$1::uuid WHERE id=$2::uuid`, newID, sid)
		}
		orig, _ := s.loadJourneyPlan(journeyID)
		split, _ := s.loadJourneyPlan(newID)
		if orig != nil {
			orig.SplitJourney = split
		}
		_ = s.Audit(actorID, role, "journey.split", "journey", journeyID, true, req)
		return 201, map[string]interface{}{"journey": orig, "splitJourney": split}, nil
	})
	if err != nil {
		return nil, err
	}
	_ = st
	return asMap(resp), nil
}

func (s *Service) MergeJourneys(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
	targetID, _ := req["targetJourneyId"].(string)
	expected := toInt(req["expectedPlanVersion"])
	sources := toStringSlice(req["sourceJourneyIds"])
	idem, _ := req["idempotencyKey"].(string)
	st, resp, err := s.Idempotent(actorID, idem, "merge_journeys", func() (int, interface{}, error) {
		plan, err := s.loadJourneyPlan(targetID)
		if err != nil {
			return 0, nil, err
		}
		if plan.PlanVersion != expected {
			return 0, nil, Err(409, "stale_plan", "plan version mismatch")
		}
		samples := append([]string{}, plan.SampleIDs...)
		for _, src := range sources {
			sp, err := s.loadJourneyPlan(src)
			if err != nil {
				return 0, nil, err
			}
			// check pulse / batching
			for _, sid := range sp.SampleIDs {
				var typeID string
				_ = s.DB.SQL.QueryRow(`SELECT sample_type_id::text FROM samples WHERE id=$1::uuid`, sid).Scan(&typeID)
				stRow, _ := s.loadSampleType(typeID)
				if stRow != nil && !stRow.BatchingAllowed {
					return 0, nil, Err(409, "pulse_no_batch", "Pulse samples cannot be batched")
				}
				// incompat
				for _, existing := range samples {
					var eType string
					_ = s.DB.SQL.QueryRow(`SELECT sample_type_id::text FROM samples WHERE id=$1::uuid`, existing).Scan(&eType)
					if stRow != nil && contains(stRow.Incompatible, eType) {
						return 0, nil, Err(409, "incompatible_batch", "incompatible samples")
					}
				}
				samples = append(samples, sid)
				_, _ = s.DB.SQL.Exec(`UPDATE samples SET active_journey_id=$1::uuid WHERE id=$2::uuid`, targetID, sid)
			}
			_, _ = s.DB.SQL.Exec(`UPDATE journeys SET status='merged', updated_at=NOW() WHERE id=$1::uuid`, src)
		}
		_, _ = s.DB.SQL.Exec(`UPDATE journeys SET sample_ids=$1, route_mode='batched', plan_version=plan_version+1, updated_at=NOW() WHERE id=$2::uuid`,
			models.MustJSON(samples), targetID)
		_ = s.Audit(actorID, role, "journey.merge", "journey", targetID, true, req)
		out, err := s.loadJourneyPlan(targetID)
		if err != nil {
			return 0, nil, err
		}
		return 201, out, nil
	})
	if err != nil {
		return nil, err
	}
	_ = st
	return asMap(resp), nil
}

func (s *Service) ReportDisruption(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
	resourceType, _ := req["resourceType"].(string)
	resourceID, _ := req["resourceId"].(string)
	reason, _ := req["reason"].(string)
	occurredAt, err := parseTimeAny(req["occurredAt"])
	if err != nil {
		return nil, Err(400, "invalid_time", "invalid occurredAt")
	}
	idem, _ := req["idempotencyKey"].(string)
	st, resp, err := s.Idempotent(actorID, idem, "report_disruption", func() (int, interface{}, error) {
		// deactivate resource
		switch resourceType {
		case "location", "node", "laboratory":
			_, _ = s.DB.SQL.Exec(`UPDATE locations SET active=FALSE WHERE id=$1::uuid`, resourceID)
		case "connection", "route":
			_, _ = s.DB.SQL.Exec(`UPDATE connections SET active=FALSE WHERE id=$1::uuid`, resourceID)
		case "worker":
			_, _ = s.DB.SQL.Exec(`UPDATE users SET available=FALSE WHERE id=$1::uuid`, resourceID)
		case "capacity":
			// leave as is; capacity change handled elsewhere
		}
		s.bumpNetwork()

		// find affected samples
		affected := []string{}
		replans := []string{}
		replanStatus := "not_required"

		var rows *sql.Rows
		switch resourceType {
		case "location", "node", "laboratory":
			rows, _ = s.DB.SQL.Query(`
				SELECT DISTINCT s.id::text FROM samples s
				JOIN assignments a ON a.sample_id = s.id
				WHERE s.status NOT IN ('received','cancelled','expired')
				AND (a.from_location_id=$1::uuid OR a.to_location_id=$1::uuid OR s.target_laboratory_id=$1::uuid)`, resourceID)
		case "connection", "route":
			rows, _ = s.DB.SQL.Query(`
				SELECT DISTINCT s.id::text FROM samples s
				WHERE s.status NOT IN ('received','cancelled','expired') AND s.active_journey_id IS NOT NULL`)
		case "worker":
			rows, _ = s.DB.SQL.Query(`
				SELECT DISTINCT s.id::text FROM samples s
				JOIN assignments a ON a.sample_id = s.id
				WHERE a.worker_id=$1::uuid AND a.status IN ('offered','accepted','in_progress')
				AND s.status NOT IN ('received','cancelled')`, resourceID)
		default:
			rows, _ = s.DB.SQL.Query(`SELECT id::text FROM samples WHERE status NOT IN ('received','cancelled','expired') AND active_journey_id IS NOT NULL`)
		}
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var sid string
				if rows.Scan(&sid) == nil {
					affected = append(affected, sid)
				}
			}
		}

		for _, sid := range affected {
			sm, err := s.loadSample(sid)
			if err != nil || !sm.ActiveJourneyID.Valid {
				continue
			}
			// preserve holder, completed work
			plan, _ := s.loadJourneyPlan(sm.ActiveJourneyID.String)
			if plan == nil {
				continue
			}
			result, err := s.RerouteJourney(actorID, role, map[string]interface{}{
				"journeyId": sm.ActiveJourneyID.String,
				"expectedPlanVersion": plan.PlanVersion,
				"idempotencyKey": fmt.Sprintf("%s-%s", idem, sid),
				"reason": reason,
			})
			if err != nil {
				replanStatus = "exception"
				continue
			}
			if rs, ok := result["replanStatus"].(string); ok {
				replanStatus = rs
			}
			if rid, ok := result["replacementPlanId"].(string); ok && rid != "" {
				replans = append(replans, rid)
			}
		}

		did := uuid.New().String()
		_, _ = s.DB.SQL.Exec(`
			INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, affected_sample_ids, replacement_plan_ids, replan_status)
			VALUES ($1::uuid,$2,$3,$4,$5,$6,$7,$8)`,
			did, resourceType, resourceID, reason, occurredAt, models.MustJSON(affected), models.MustJSON(replans), replanStatus)
		_ = s.Audit(actorID, role, "disruption.report", "disruption", did, true, req)
		return 201, map[string]interface{}{
			"disruptionId":       did,
			"affectedSampleIds":  affected,
			"replacementPlanIds": replans,
			"replanStatus":       replanStatus,
		}, nil
	})
	if err != nil {
		return nil, err
	}
	_ = st
	return asMap(resp), nil
}

func (s *Service) ListRoleWork(sess *SessionInfo, roleFilter, statusFilter string) (map[string]interface{}, error) {
	role := sess.ActiveRole
	if roleFilter != "" {
		role = roleFilter
	}
	if role == "" {
		return nil, Err(409, "role_not_selected", "select an active role")
	}
	pending := []interface{}{}
	inProgress := []interface{}{}
	completed := []interface{}{}

	switch role {
	case models.RoleRequester:
		rows, err := s.DB.SQL.Query(`
			SELECT id::text, status, request_id::text, delivery_deadline, active_journey_id::text
			FROM samples WHERE requester_id=$1::uuid ORDER BY created_at DESC`, sess.UserID)
		if err != nil {
			return nil, err
		}
		defer rows.Close()
		for rows.Next() {
			var id, status, reqID string
			var deadline time.Time
			var jid sql.NullString
			if rows.Scan(&id, &status, &reqID, &deadline, &jid) != nil {
				continue
			}
			item := map[string]interface{}{
				"workType": "sample", "sampleId": id, "status": status,
				"requestId": reqID, "deliveryDeadline": deadline.UTC(),
			}
			if jid.Valid {
				item["journeyId"] = jid.String
			}
			timeline := s.GetTimeline(id)
			item["timeline"] = timeline
			switch status {
			case "received", "cancelled", "expired":
				completed = append(completed, item)
			case "requested", "offered":
				pending = append(pending, item)
			default:
				inProgress = append(inProgress, item)
			}
		}
	case models.RoleDispatcher, models.RoleAdministrator:
		rows, err := s.DB.SQL.Query(`
			SELECT id::text, status, plan_version, route_mode, sample_ids FROM journeys ORDER BY created_at DESC LIMIT 200`)
		if err != nil {
			return nil, err
		}
		defer rows.Close()
		for rows.Next() {
			var id, status, mode string
			var ver int
			var sids []byte
			if rows.Scan(&id, &status, &ver, &mode, &sids) != nil {
				continue
			}
			item := map[string]interface{}{
				"workType": "journey", "journeyId": id, "status": status,
				"planVersion": ver, "routeMode": mode, "sampleIds": models.ParseStringSlice(sids),
			}
			switch status {
			case "completed", "cancelled", "replaced", "merged":
				completed = append(completed, item)
			case "planned":
				pending = append(pending, item)
			default:
				inProgress = append(inProgress, item)
			}
		}
	default:
		// worker assignments
		rows, err := s.DB.SQL.Query(`
			SELECT id::text, status, assignment_type, sample_id::text, journey_id::text, progress_status,
				from_location_id::text, to_location_id::text, sequence
			FROM assignments
			WHERE (worker_id=$1::uuid OR offered_to=$1::uuid)
			ORDER BY created_at DESC LIMIT 200`, sess.UserID)
		if err != nil {
			return nil, err
		}
		defer rows.Close()
		for rows.Next() {
			var id, status, aType string
			var sampleID, journeyID, fromID, toID sql.NullString
			var progress string
			var seq int
			if rows.Scan(&id, &status, &aType, &sampleID, &journeyID, &progress, &fromID, &toID, &seq) != nil {
				continue
			}
			item := map[string]interface{}{
				"workType": "assignment", "assignmentId": id, "status": status,
				"assignmentType": aType, "sequence": seq,
			}
			if sampleID.Valid {
				item["sampleId"] = sampleID.String
				item["timeline"] = s.GetTimeline(sampleID.String)
			}
			if journeyID.Valid {
				item["journeyId"] = journeyID.String
			}
			if fromID.Valid {
				item["fromLocationId"] = fromID.String
			}
			if toID.Valid {
				item["toLocationId"] = toID.String
			}
			if progress != "" {
				item["progressStatus"] = progress
			}
			switch status {
			case "completed", "cancelled":
				completed = append(completed, item)
			case "offered", "pending":
				pending = append(pending, item)
			default:
				inProgress = append(inProgress, item)
			}
		}
	}

	_ = statusFilter
	return map[string]interface{}{
		"pending":    pending,
		"inProgress": inProgress,
		"completed":  completed,
	}, nil
}

func (s *Service) ReadOperationsState(sess *SessionInfo, filters map[string]interface{}) (map[string]interface{}, error) {
	role := sess.ActiveRole
	if role != models.RoleAdministrator && role != models.RoleDispatcher &&
		role != models.RoleNodeHandler && role != models.RoleLaboratoryTeam {
		return nil, Err(403, "forbidden", "operations view not allowed")
	}

	samples := []map[string]interface{}{}
	srows, err := s.DB.SQL.Query(`
		SELECT id::text, status, request_id::text, origin_lat, origin_lng, delivery_deadline,
			current_holder_id::text, active_journey_id::text, latest_lat, latest_lng, location_recorded_at
		FROM samples ORDER BY created_at DESC LIMIT 500`)
	if err != nil {
		return nil, err
	}
	defer srows.Close()
	for srows.Next() {
		var id, status, reqID string
		var olat, olng float64
		var deadline time.Time
		var holder, jid sql.NullString
		var llat, llng sql.NullFloat64
		var locAt sql.NullTime
		if srows.Scan(&id, &status, &reqID, &olat, &olng, &deadline, &holder, &jid, &llat, &llng, &locAt) != nil {
			continue
		}
		item := map[string]interface{}{
			"sampleId": id, "status": status, "requestId": reqID,
			"origin": models.Coordinate{Latitude: olat, Longitude: olng},
			"deliveryDeadline": deadline.UTC(),
			"locationStale": true,
		}
		if holder.Valid {
			item["currentHolderId"] = holder.String
		}
		if jid.Valid {
			item["activeJourneyId"] = jid.String
		}
		if llat.Valid && llng.Valid {
			item["latestLocation"] = models.Coordinate{Latitude: llat.Float64, Longitude: llng.Float64}
			if locAt.Valid {
				t := locAt.Time.UTC()
				item["locationRecordedAt"] = t
				item["locationStale"] = isStale(&t, s.Cfg.LocationStaleSec)
			}
		}
		samples = append(samples, item)
	}

	workers := []map[string]interface{}{}
	wrows, err := s.DB.SQL.Query(`
		SELECT id::text, full_name, roles, available, capacity_units, latest_lat, latest_lng, location_recorded_at,
			(SELECT COUNT(*) FROM assignments a WHERE a.worker_id=users.id AND a.status IN ('offered','accepted','in_progress'))
		FROM users WHERE roles::text LIKE '%collection%' OR roles::text LIKE '%delivery%' OR roles::text LIKE '%node%' OR roles::text LIKE '%laboratory%'`)
	if err != nil {
		return nil, err
	}
	defer wrows.Close()
	assignCounts := []int{}
	for wrows.Next() {
		var id, name string
		var rolesJSON []byte
		var available bool
		var cap, acount int
		var lat, lng sql.NullFloat64
		var locAt sql.NullTime
		if wrows.Scan(&id, &name, &rolesJSON, &available, &cap, &lat, &lng, &locAt, &acount) != nil {
			continue
		}
		st := "unavailable"
		if available {
			st = "available"
		}
		item := map[string]interface{}{
			"workerId": id, "fullName": name, "roles": models.ParseStringSlice(rolesJSON),
			"available": available, "status": st, "capacityUnits": cap,
			"assignmentCount": acount, "locationStale": true,
		}
		if lat.Valid && lng.Valid {
			item["latestLocation"] = models.Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
			if locAt.Valid {
				t := locAt.Time.UTC()
				item["locationRecordedAt"] = t
				item["locationStale"] = isStale(&t, s.Cfg.LocationStaleSec)
			}
		}
		workers = append(workers, item)
		assignCounts = append(assignCounts, acount)
	}

	locations := []map[string]interface{}{}
	locs, _ := s.loadLocations()
	for _, l := range locs {
		// filter for node_handler / lab team
		if role == models.RoleNodeHandler || role == models.RoleLaboratoryTeam {
			var assigned sql.NullString
			_ = s.DB.SQL.QueryRow(`SELECT assigned_location_id::text FROM users WHERE id=$1::uuid`, sess.UserID).Scan(&assigned)
			if !assigned.Valid || assigned.String != l.ID {
				continue
			}
		}
		cap := models.Capacity{
			CapacityUnits: l.CapacityUnits, ReservedUnits: l.ReservedUnits,
			CooledCapacityUnits: l.CooledCap, CooledReservedUnits: l.CooledReserved,
		}.Normalize()
		item := map[string]interface{}{
			"id": l.ID, "locationId": l.ID, "name": l.Name,
			"coordinate": models.Coordinate{Latitude: l.Lat, Longitude: l.Lng},
			"active": l.Active, "coverageKm": l.CoverageKm, "handlingMinutes": l.HandlingMinutes,
			"functions": models.LocationFunctions{
				CollectionPoint: l.CollectionPoint, TransferPoint: l.TransferPoint,
				Hub: l.Hub, Laboratory: l.Laboratory,
			},
			"capacity": cap,
			"acceptedSampleTypeIds": l.AcceptedTypes,
		}
		locations = append(locations, item)
	}

	connections := []map[string]interface{}{}
	conns, _ := s.loadConnections()
	for _, c := range conns {
		cap := models.Capacity{
			CapacityUnits: c.CapacityUnits, ReservedUnits: c.ReservedUnits,
			CooledCapacityUnits: c.CooledCap, CooledReservedUnits: c.CooledReserved,
		}.Normalize()
		connections = append(connections, map[string]interface{}{
			"id": c.ID, "connectionId": c.ID,
			"fromLocationId": c.FromID, "toLocationId": c.ToID,
			"travelMinutes": c.TravelMinutes, "costUnits": c.CostUnits,
			"cooled": c.Cooled, "active": c.Active, "capacity": cap,
		})
	}

	routes := []map[string]interface{}{}
	jrows, _ := s.DB.SQL.Query(`SELECT id::text, status, route_mode, sample_ids FROM journeys WHERE status NOT IN ('cancelled') LIMIT 100`)
	if jrows != nil {
		defer jrows.Close()
		for jrows.Next() {
			var id, status, mode string
			var sids []byte
			if jrows.Scan(&id, &status, &mode, &sids) == nil {
				routes = append(routes, map[string]interface{}{
					"journeyId": id, "status": status, "routeMode": mode, "sampleIds": models.ParseStringSlice(sids),
				})
			}
		}
	}

	handoffs := []map[string]interface{}{}
	hrows, _ := s.DB.SQL.Query(`SELECT id::text, sample_id::text, sender_id::text, receiver_id::text, status FROM handoffs ORDER BY created_at DESC LIMIT 100`)
	if hrows != nil {
		defer hrows.Close()
		for hrows.Next() {
			var id, sid, sender, receiver, status string
			if hrows.Scan(&id, &sid, &sender, &receiver, &status) == nil {
				handoffs = append(handoffs, map[string]interface{}{
					"handoffId": id, "sampleId": sid, "senderId": sender, "receiverId": receiver, "status": status,
				})
			}
		}
	}

	exceptions := []map[string]interface{}{}
	erows, _ := s.DB.SQL.Query(`SELECT id::text, status, exception FROM samples WHERE exception IS NOT NULL AND exception::text <> 'null' LIMIT 100`)
	if erows != nil {
		defer erows.Close()
		for erows.Next() {
			var id, status string
			var exc []byte
			if erows.Scan(&id, &status, &exc) == nil {
				var e interface{}
				_ = json.Unmarshal(exc, &e)
				exceptions = append(exceptions, map[string]interface{}{"sampleId": id, "status": status, "exception": e})
			}
		}
	}

	// assignment count spread
	spread := 0
	if len(assignCounts) > 0 {
		minC, maxC := assignCounts[0], assignCounts[0]
		for _, c := range assignCounts {
			if c < minC {
				minC = c
			}
			if c > maxC {
				maxC = c
			}
		}
		spread = maxC - minC
	}

	ineligible := 0
	_ = s.DB.SQL.QueryRow(`SELECT COUNT(*) FROM samples WHERE status='exception' AND exception::text LIKE '%no_qualified_worker%'`).Scan(&ineligible)

	_ = filters
	return map[string]interface{}{
		"samples":                   samples,
		"workers":                   workers,
		"locations":                 locations,
		"connections":               connections,
		"routes":                    routes,
		"handoffs":                  handoffs,
		"delays":                    []interface{}{},
		"exceptions":                exceptions,
		"assignmentCountSpread":     spread,
		"ineligibleAssignmentCount": ineligible,
	}, nil
}

func (s *Service) SearchAuditTrail(sess *SessionInfo, req map[string]interface{}) (map[string]interface{}, error) {
	if sess.ActiveRole != models.RoleAdministrator && sess.ActiveRole != models.RoleDispatcher {
		return nil, Err(403, "forbidden", "audit search not allowed")
	}
	limit := 500
	if v, ok := req["limit"]; ok {
		limit = toInt(v)
		if limit < 1 {
			limit = 500
		}
		if limit > 5000 {
			limit = 5000
		}
	}
	offset := 0
	if v, ok := req["offset"]; ok {
		offset = toInt(v)
	}
	order := "newest_first"
	if v, ok := req["order"].(string); ok && v != "" {
		order = v
	}
	orderSQL := "occurred_at DESC, id DESC"
	if order == "oldest_first" {
		orderSQL = "occurred_at ASC, id ASC"
	}

	where := []string{"1=1"}
	args := []interface{}{}
	idx := 1
	if q, ok := req["query"].(string); ok && q != "" {
		where = append(where, fmt.Sprintf(`(action ILIKE $%d OR entity_id ILIKE $%d OR actor_id ILIKE $%d OR details::text ILIKE $%d)`, idx, idx, idx, idx))
		args = append(args, "%"+q+"%")
		idx++
	}
	if v, ok := req["actorId"].(string); ok && v != "" {
		where = append(where, fmt.Sprintf("actor_id=$%d", idx))
		args = append(args, v)
		idx++
	}
	if v, ok := req["entityType"].(string); ok && v != "" {
		where = append(where, fmt.Sprintf("entity_type=$%d", idx))
		args = append(args, v)
		idx++
	}
	if v, ok := req["entityId"].(string); ok && v != "" {
		where = append(where, fmt.Sprintf("entity_id=$%d", idx))
		args = append(args, v)
		idx++
	}
	if v, ok := req["action"].(string); ok && v != "" {
		where = append(where, fmt.Sprintf("action=$%d", idx))
		args = append(args, v)
		idx++
	}
	if v, ok := req["role"].(string); ok && v != "" {
		where = append(where, fmt.Sprintf("role=$%d", idx))
		args = append(args, v)
		idx++
	}
	if v, ok := req["success"].(bool); ok {
		where = append(where, fmt.Sprintf("success=$%d", idx))
		args = append(args, v)
		idx++
	}
	if v, ok := req["fromTime"].(string); ok && v != "" {
		t, err := parseTimeAny(v)
		if err == nil {
			where = append(where, fmt.Sprintf("occurred_at >= $%d", idx))
			args = append(args, t)
			idx++
		}
	}
	if v, ok := req["toTime"].(string); ok && v != "" {
		t, err := parseTimeAny(v)
		if err == nil {
			where = append(where, fmt.Sprintf("occurred_at <= $%d", idx))
			args = append(args, t)
			idx++
		}
	}

	whereSQL := strings.Join(where, " AND ")
	countQ := fmt.Sprintf(`SELECT COUNT(*) FROM audit_log WHERE %s`, whereSQL)
	var total int
	_ = s.DB.SQL.QueryRow(countQ, args...).Scan(&total)

	args2 := append(args, limit, offset)
	q := fmt.Sprintf(`
		SELECT audit_id::text, actor_id, role, action, entity_type, entity_id, success, occurred_at, details
		FROM audit_log WHERE %s ORDER BY %s LIMIT $%d OFFSET $%d`, whereSQL, orderSQL, idx, idx+1)
	rows, err := s.DB.SQL.Query(q, args2...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	entries := []map[string]interface{}{}
	for rows.Next() {
		var auditID, actorID, role, action, et, eid string
		var success bool
		var occurred time.Time
		var details []byte
		if rows.Scan(&auditID, &actorID, &role, &action, &et, &eid, &success, &occurred, &details) != nil {
			continue
		}
		var det map[string]interface{}
		_ = json.Unmarshal(details, &det)
		if det == nil {
			det = map[string]interface{}{}
		}
		entries = append(entries, map[string]interface{}{
			"auditId": auditID, "audit_id": auditID,
			"actorId": actorID, "actor_id": actorID,
			"role": role, "actorRole": role,
			"action": action,
			"entityType": et, "entity_type": et,
			"entityId": eid, "entity_id": eid,
			"success": success,
			"occurredAt": occurred.UTC(), "occurred_at": occurred.UTC(),
			"details": det,
		})
	}

	// also try mongo for completeness
	_ = options.Find()
	_ = bson.M{}

	return map[string]interface{}{
		"entries": entries,
		"total":   total,
		"limit":   limit,
		"offset":  offset,
	}, nil
}

func (s *Service) UIBootstrap(sess *SessionInfo) (map[string]interface{}, error) {
	roleRequired := sess.ActiveRole == "" && len(sess.Roles) > 1
	if len(sess.Roles) == 1 && sess.ActiveRole == "" {
		sess.ActiveRole = sess.Roles[0]
		_, _ = s.DB.SQL.Exec(`UPDATE sessions SET active_role=$1 WHERE token=$2`, sess.ActiveRole, sess.Token)
		roleRequired = false
	}
	user := map[string]interface{}{
		"userId":                sess.UserID,
		"username":              sess.Username,
		"fullName":              sess.FullName,
		"roles":                 sess.Roles,
		"activeRole":            sess.ActiveRole,
		"roleSelectionRequired": roleRequired,
	}
	out := map[string]interface{}{
		"user":       user,
		"serverTime": nowUTC(),
	}
	if sess.ActiveRole == models.RoleRequester || contains(sess.Roles, models.RoleRequester) {
		samples := []map[string]interface{}{}
		rows, _ := s.DB.SQL.Query(`SELECT id::text, status, delivery_deadline FROM samples WHERE requester_id=$1::uuid ORDER BY created_at DESC LIMIT 50`, sess.UserID)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var id, status string
				var dl time.Time
				if rows.Scan(&id, &status, &dl) == nil {
					samples = append(samples, map[string]interface{}{"sampleId": id, "status": status, "deliveryDeadline": dl.UTC()})
				}
			}
		}
		out["requesterSamples"] = samples
	}
	if isDispatcherLike(sess.ActiveRole) || sess.ActiveRole == models.RoleNodeHandler || sess.ActiveRole == models.RoleLaboratoryTeam {
		ops, err := s.ReadOperationsState(sess, nil)
		if err == nil {
			out["operations"] = ops
		}
	}
	return out, nil
}

func isDispatcherLike(role string) bool {
	return role == models.RoleAdministrator || role == models.RoleDispatcher
}

func (s *Service) EventsSince(since int64) []Event {
	rows, err := s.DB.SQL.Query(`
		SELECT id, type, entity_type, entity_id, payload, created_at, audience_roles
		FROM realtime_events WHERE id > $1 ORDER BY id ASC LIMIT 1000`, since)
	if err != nil {
		return nil
	}
	defer rows.Close()
	out := []Event{}
	for rows.Next() {
		var e Event
		var payload, audience []byte
		var created time.Time
		if rows.Scan(&e.ID, &e.Type, &e.EntityType, &e.EntityID, &payload, &created, &audience) != nil {
			continue
		}
		e.CreatedAt = created.UTC()
		_ = json.Unmarshal(payload, &e.Payload)
		if e.Payload == nil {
			e.Payload = map[string]interface{}{}
		}
		_ = json.Unmarshal(audience, &e.Audience)
		out = append(out, e)
	}
	return out
}
"}

