var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}

func (a *API) EventsWS(w http.ResponseWriter, r *http.Request) {
	// auth via subprotocol or query
	token := auth.ExtractBearer(r)
	if token == "" {
		token = auth.ExtractWSToken(websocket.Subprotocols(r))
	}
	if token == "" {
		token = r.URL.Query().Get("token")
	}
	sess, err := a.Svc.ResolveSession(token)
	if err != nil {
		writeError(w, 401, "unauthorized", "unauthorized")
		return
	}
	since := int64(0)
	if s := r.URL.Query().Get("since"); s != "" {
		since, _ = strconv.ParseInt(s, 10, 64)
	}

	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()

	// replay
	for _, ev := range a.Svc.EventsSince(since) {
		_ = conn.WriteJSON(map[string]interface{}{
			"id": ev.ID, "type": ev.Type, "entityType": ev.EntityType,
			"entityId": ev.EntityID, "payload": ev.Payload, "createdAt": ev.CreatedAt,
		})
	}

	ch := a.Svc.Hub().Subscribe(sess.ActiveRole)
	defer a.Svc.Hub().Unsubscribe(ch)

	done := make(chan struct{})
	go func() {
		defer close(done)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				return
			}
		}
	}()

	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-done:
			return
		case ev, ok := <-ch:
			if !ok {
				return
			}
			if err := conn.WriteJSON(map[string]interface{}{
				"id": ev.ID, "type": ev.Type, "entityType": ev.EntityType,
				"entityId": ev.EntityID, "payload": ev.Payload, "createdAt": ev.CreatedAt,
			}); err != nil {
				return
			}
		case <-ticker.C:
			if err := conn.WriteControl(websocket.PingMessage, []byte("ping"), time.Now().Add(5*time.Second)); err != nil {
				return
			}
		}
	}
}

func toF(v interface{}) float64 {
	switch t := v.(type) {
	case float64:
		return t
	case int:
		return float64(t)
	case json.Number:
		f, _ := t.Float64()
		return f
	}
	return 0
}

