func (a *API) ReadUser(w http.ResponseWriter, r *http.Request) {
	uid := mux.Vars(r)["userId"]
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		if sess.UserID != uid {
			if err := requireRole(sess, models.RoleAdministrator, models.RoleDispatcher); err != nil {
