func (a *API) Authenticate(w http.ResponseWriter, r *http.Request) {
	var body map[string]interface{}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeError(w, 400, "invalid_json", "invalid json")
		return
	}
	username, _ := body["username"].(string)
	password, _ := body["password"].(string)
	if username == "" || password == "" {
		writeError(w, 400, "invalid_json", "username and password required")
		return
	}
	sess, err := a.Svc.Authenticate(username, password)
	if err != nil {
		if ae, ok := err.(*service.AppError); ok {
			writeError(w, ae.Status, ae.Code, ae.Message)
			return
		}
		writeError(w, 500, "internal_error", err.Error())
		return
	}
	writeData(w, 200, map[string]interface{}{
		"sessionToken": sess.Token,
		"userId":       sess.UserID,
		"roles":        sess.Roles,
		"activeRole":   sess.ActiveRole,
	})
}

