package handlers

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"strconv"
	"strings"
	"time"

	"lablogistics/internal/auth"
	"lablogistics/internal/models"
	"lablogistics/internal/service"

	"github.com/gorilla/mux"
	"github.com/gorilla/websocket"
)

type API struct {
	Svc *service.Service
}

func New(svc *service.Service) *API {
	return &API{Svc: svc}
}

func (a *API) Router(staticDir, mapAssetsDir string) http.Handler {
	r := mux.NewRouter()

	r.HandleFunc("/ready", a.Ready).Methods("GET")

	api := r.PathPrefix("/api").Subrouter()
	api.HandleFunc("/authenticate-user", a.Authenticate).Methods("POST")

	// authenticated routes
	authz := api.NewRoute().Subrouter()
	authz.Use(a.authMiddleware)

	authz.HandleFunc("/select-active-role", a.SelectActiveRole).Methods("POST")
	authz.HandleFunc("/ui/bootstrap", a.UIBootstrap).Methods("GET")
	authz.HandleFunc("/create-user", a.CreateUser).Methods("POST")
	authz.HandleFunc("/update-user-access", a.UpdateUserAccess).Methods("POST")
	authz.HandleFunc("/read-user/{userId}", a.ReadUser).Methods("GET")
	authz.HandleFunc("/create-location", a.CreateLocation).Methods("POST")
	authz.HandleFunc("/update-location", a.UpdateLocation).Methods("POST")
	authz.HandleFunc("/set-location-status", a.SetLocationStatus).Methods("POST")
	authz.HandleFunc("/set-location-function-status", a.SetLocationFunctionStatus).Methods("POST")
	authz.HandleFunc("/create-connection", a.CreateConnection).Methods("POST")
	authz.HandleFunc("/set-connection-status", a.SetConnectionStatus).Methods("POST")
	authz.HandleFunc("/create-sample-type", a.CreateSampleType).Methods("POST")
	authz.HandleFunc("/update-sample-type", a.UpdateSampleType).Methods("POST")
	authz.HandleFunc("/configure-laboratory-acceptance", a.ConfigureLabAcceptance).Methods("POST")
	authz.HandleFunc("/configure-capacity", a.ConfigureCapacity).Methods("POST")
	authz.HandleFunc("/check-serviceability", a.CheckServiceability).Methods("POST")
	authz.HandleFunc("/read-serviceability-snapshot", a.ReadServiceabilitySnapshot).Methods("POST")
	authz.HandleFunc("/create-collection-request", a.CreateCollectionRequest).Methods("POST")
	authz.HandleFunc("/ingest-presealed-sample", a.IngestPresealed).Methods("POST")
	authz.HandleFunc("/read-sample-state/{sampleId}", a.ReadSampleState).Methods("GET")
	authz.HandleFunc("/read-sample-lifecycle", a.ReadSampleLifecycle).Methods("POST")
	authz.HandleFunc("/read-journey-plan", a.ReadJourneyPlan).Methods("POST")
	authz.HandleFunc("/list-role-work", a.ListRoleWork).Methods("POST")
	authz.HandleFunc("/read-operations-state", a.ReadOperationsState).Methods("POST")
	authz.HandleFunc("/accept-assignment", a.AcceptAssignment).Methods("POST")
	authz.HandleFunc("/decline-assignment", a.DeclineAssignment).Methods("POST")
	authz.HandleFunc("/collect-and-seal-sample", a.CollectAndSeal).Methods("POST")
	authz.HandleFunc("/initiate-handoff", a.InitiateHandoff).Methods("POST")
	authz.HandleFunc("/confirm-handoff", a.ConfirmHandoff).Methods("POST")
	authz.HandleFunc("/confirm-laboratory-receipt", a.ConfirmLabReceipt).Methods("POST")
	authz.HandleFunc("/record-laboratory-exception", a.RecordLabException).Methods("POST")
	authz.HandleFunc("/record-handling-checkpoint", a.RecordHandlingCheckpoint).Methods("POST")
	authz.HandleFunc("/record-worker-location", a.RecordWorkerLocation).Methods("POST")
	authz.HandleFunc("/update-assignment-progress", a.UpdateAssignmentProgress).Methods("POST")
	authz.HandleFunc("/set-worker-availability", a.SetWorkerAvailability).Methods("POST")
	authz.HandleFunc("/cancel-journey", a.CancelJourney).Methods("POST")
	authz.HandleFunc("/reroute-journey", a.RerouteJourney).Methods("POST")
	authz.HandleFunc("/edit-active-plan", a.EditActivePlan).Methods("POST")
	authz.HandleFunc("/split-journey", a.SplitJourney).Methods("POST")
	authz.HandleFunc("/merge-journeys", a.MergeJourneys).Methods("POST")
	authz.HandleFunc("/report-disruption", a.ReportDisruption).Methods("POST")
	authz.HandleFunc("/search-audit-trail", a.SearchAuditTrail).Methods("POST")
	authz.HandleFunc("/events", a.EventsWS).Methods("GET")

	// map assets
	r.PathPrefix("/map-assets/").Handler(http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapAssetsDir))))

	// SPA static
	r.PathPrefix("/").Handler(spaHandler(staticDir))

	return cors(r)
}

func cors(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func spaHandler(staticDir string) http.Handler {
	fs := http.FileServer(http.Dir(staticDir))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := staticDir + r.URL.Path
		if r.URL.Path == "/" || strings.HasPrefix(r.URL.Path, "/assets") || fileExists(path) {
			fs.ServeHTTP(w, r)
			return
		}
		http.ServeFile(w, r, staticDir+"/index.html")
	})
}

func fileExists(p string) bool {
	f, err := http.Dir("/").Open(strings.TrimPrefix(p, "/"))
	if err != nil {
		// try direct
		if st, err2 := http.Dir(p).Open("."); err2 == nil {
			_ = st.Close()
			return true
		}
		return false
	}
	_ = f.Close()
	return true
}

func (a *API) authMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		token := auth.ExtractBearer(r)
		sess, err := a.Svc.ResolveSession(token)
		if err != nil {
			if ae, ok := err.(*service.AppError); ok {
				writeError(w, ae.Status, ae.Code, ae.Message)
				return
			}
			writeError(w, 401, "unauthorized", "unauthorized")
			return
		}
		ctx := context.WithValue(r.Context(), CtxUserID, sess.UserID)
		ctx = context.WithValue(ctx, CtxActiveRole, sess.ActiveRole)
		ctx = context.WithValue(ctx, CtxRoles, sess.Roles)
		ctx = context.WithValue(ctx, CtxUsername, sess.Username)
		ctx = context.WithValue(ctx, ctxKey("session"), sess)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func sessFrom(r *http.Request) *service.SessionInfo {
	if v := r.Context().Value(ctxKey("session")); v != nil {
		return v.(*service.SessionInfo)
	}
	return &service.SessionInfo{
		UserID:     strCtx(r, CtxUserID),
		ActiveRole: strCtx(r, CtxActiveRole),
		Username:   strCtx(r, CtxUsername),
	}
}

func strCtx(r *http.Request, k ctxKey) string {
	if v := r.Context().Value(k); v != nil {
		if s, ok := v.(string); ok {
			return s
		}
	}
	return ""
}

func (a *API) handle(w http.ResponseWriter, r *http.Request, fn func(map[string]interface{}, *service.SessionInfo) (int, interface{}, error)) {
	sess := sessFrom(r)
	var body map[string]interface{}
	if r.Method != http.MethodGet && r.Body != nil {
		b, err := io.ReadAll(r.Body)
		if err != nil {
			writeError(w, 400, "invalid_json", "invalid body")
			return
		}
		if len(b) > 0 {
			dec := json.NewDecoder(strings.NewReader(string(b)))
			dec.UseNumber()
			if err := dec.Decode(&body); err != nil {
				writeError(w, 400, "invalid_json", "invalid json")
				return
			}
		}
	}
	if body == nil {
		body = map[string]interface{}{}
	}
	// normalize json.Number
	body = normalize(body).(map[string]interface{})

	status, data, err := fn(body, sess)
	if err != nil {
		if ae, ok := err.(*service.AppError); ok {
			writeError(w, ae.Status, ae.Code, ae.Message)
			return
		}
		writeError(w, 500, "internal_error", err.Error())
		return
	}
	if status == 0 {
		status = 200
	}
	writeData(w, status, data)
}

func normalize(v interface{}) interface{} {
	switch t := v.(type) {
	case map[string]interface{}:
		out := map[string]interface{}{}
		for k, val := range t {
			out[k] = normalize(val)
		}
		return out
	case []interface{}:
		out := make([]interface{}, len(t))
		for i, val := range t {
			out[i] = normalize(val)
		}
		return out
	case json.Number:
		if i, err := t.Int64(); err == nil {
			return float64(i)
		}
		f, _ := t.Float64()
		return f
	default:
		return v
	}
}

func requireRole(sess *service.SessionInfo, roles ...string) error {
	if sess.ActiveRole == "" {
		if len(sess.Roles) == 1 {
			sess.ActiveRole = sess.Roles[0]
		} else {
			return service.Err(409, "role_not_selected", "select an active role")
		}
	}
	for _, role := range roles {
		if sess.ActiveRole == role {
			return nil
		}
		// administrator may act as dispatcher for admin-only if listed
		if sess.ActiveRole == models.RoleAdministrator && (role == models.RoleDispatcher || role == models.RoleAdministrator) {
			return nil
		}
	}
	return service.Err(403, "forbidden", "forbidden for role "+sess.ActiveRole)
}

func requireAnyWorker(sess *service.SessionInfo) error {
	return requireRole(sess,
		models.RoleCollectionProfessional,
		models.RoleDeliveryPartner,
		models.RoleNodeHandler,
		models.RoleLaboratoryTeam,
		models.RoleAdministrator,
		models.RoleDispatcher,
	)
}

// ---- handlers ----

func (a *API) Ready(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 3*time.Second)
	defer cancel()
	if err := a.Svc.DB.Ready(ctx); err != nil {
		writeJSON(w, 503, map[string]string{"status": "starting"})
		return
	}
	writeJSON(w, 200, map[string]string{"status": "ready"})
}

func (a *API) Authenticate(w http.ResponseWriter, r *http.Request) {
	var body map[string]interface{}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeError(w, 400, "invalid_json", "invalid json")
		return
	}
	username, _ := body["username"].(string)
	password, _ := body["password"].(string)
	if username == "" || password == "" {
		writeError(w, 400, "invalid_json", "username and password required")
		return
	}
	sess, err := a.Svc.Authenticate(username, password)
	if err != nil {
		if ae, ok := err.(*service.AppError); ok {
			writeError(w, ae.Status, ae.Code, ae.Message)
			return
		}
		writeError(w, 500, "internal_error", err.Error())
		return
	}
	writeData(w, 200, map[string]interface{}{
		"sessionToken": sess.Token,
		"userId":       sess.UserID,
		"roles":        sess.Roles,
		"activeRole":   sess.ActiveRole,
	})
}

func (a *API) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		role, _ := body["role"].(string)
		active, roles, err := a.Svc.SelectRole(sess.UserID, role, sess.Roles)
		if err != nil {
			return 0, nil, err
		}
		return 200, map[string]interface{}{"activeRole": active, "roles": roles}, nil
	})
}

func (a *API) UIBootstrap(w http.ResponseWriter, r *http.Request) {
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		out, err := a.Svc.UIBootstrap(sess)
		return 200, out, err
	})
}

func (a *API) CreateUser(w http.ResponseWriter, r *http.Request) {
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		if err := requireRole(sess, models.RoleAdministrator); err != nil {
			return 0, nil, err
		}
		out, err := a.Svc.CreateUser(sess.UserID, sess.ActiveRole, body)
		return 201, out, err
	})
}

func (a *API) UpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		if err := requireRole(sess, models.RoleAdministrator); err != nil {
			return 0, nil, err
		}
		uid, _ := body["userId"].(string)
		out, err := a.Svc.UpdateUserAccess(sess.UserID, sess.ActiveRole, uid, body)
		return 201, out, err
	})
}

func (a *API) ReadUser(w http.ResponseWriter, r *http.Request) {
	uid := mux.Vars(r)["userId"]
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		if sess.UserID != uid {
			if err := requireRole(sess, models.RoleAdministrator, models.RoleDispatcher); err != nil {
				return 0, nil, err
			}
		}
		out, err := a.Svc.ReadUser(uid)
		return 200, out, err
	})
}

func (a *API) CreateLocation(w http.ResponseWriter, r *http.Request) {
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		if err := requireRole(sess, models.RoleAdministrator); err != nil {
			return 0, nil, err
		}
		out, err := a.Svc.CreateLocation(sess.UserID, sess.ActiveRole, body)
		return 201, out, err
	})
}

func (a *API) UpdateLocation(w http.ResponseWriter, r *http.Request) {
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		if err := requireRole(sess, models.RoleAdministrator); err != nil {
			return 0, nil, err
		}
		out, err := a.Svc.UpdateLocation(sess.UserID, sess.ActiveRole, body)
		return 201, out, err
	})
}

func (a *API) SetLocationStatus(w http.ResponseWriter, r *http.Request) {
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		if err := requireRole(sess, models.RoleAdministrator); err != nil {
			return 0, nil, err
