func (a *API) SetLocationFunctionStatus(w http.ResponseWriter, r *http.Request) {
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		if err := requireRole(sess, models.RoleAdministrator); err != nil {
			return 0, nil, err
		}
		id, _ := body["locationId"].(string)
		fn, _ := body["function"].(string)
		active, _ := body["active"].(bool)
		out, err := a.Svc.SetLocationFunctionStatus(sess.UserID, sess.ActiveRole, id, fn, active)
		return 200, out, err
	})
}

func (a *API) CreateConnection(w http.ResponseWriter, r *http.Request) {
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		if err := requireRole(sess, models.RoleAdministrator); err != nil {
			return 0, nil, err
		}
		out, err := a.Svc.CreateConnection(sess.UserID, sess.ActiveRole, body)
		return 201, out, err
