}

func (a *API) SetConnectionStatus(w http.ResponseWriter, r *http.Request) {
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		if err := requireRole(sess, models.RoleAdministrator); err != nil {
			return 0, nil, err
		}
		id, _ := body["connectionId"].(string)
		active, _ := body["active"].(bool)
		out, err := a.Svc.SetConnectionStatus(sess.UserID, sess.ActiveRole, id, active)
		return 200, out, err
