	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		if err := requireRole(sess, models.RoleAdministrator, models.RoleDispatcher, models.RoleLaboratoryTeam); err != nil {
