func (a *API) ConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	a.handle(w, r, func(body map[string]interface{}, sess *service.SessionInfo) (int, interface{}, error) {
		if err := requireRole(sess, models.RoleAdministrator, models.RoleDispatcher, models.RoleNodeHandler, models.RoleLaboratoryTeam); err != nil {
			return 0, nil, err
		}
		rid, _ := body["resourceId"].(string)
		units := int(toF(body["capacityUnits"]))
