:root {
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  color: #0f172a;
  background: #f1f5f9;
  line-height: 1.45;
}
* { box-sizing: border-box; }
body { margin: 0; }
button, input, select, textarea {
  font: inherit;
}
a { color: #0f766e; }
.app-shell { min-height: 100vh; display: flex; flex-direction: column; }
.topbar {
  display: flex; align-items: center; justify-content: space-between;
  gap: 1rem; padding: 0.75rem 1.25rem; background: #0f766e; color: white;
}
.topbar h1 { font-size: 1.1rem; margin: 0; font-weight: 600; }
.topbar .meta { display: flex; gap: 0.75rem; align-items: center; flex-wrap: wrap; }
.topbar button, .panel button, .btn {
  background: #115e59; color: white; border: 1px solid #134e4a;
  border-radius: 8px; padding: 0.4rem 0.8rem; cursor: pointer;
}
.topbar button.secondary, .btn.secondary { background: #334155; border-color: #1e293b; }
.topbar button:hover, .btn:hover { filter: brightness(1.08); }
.layout { display: grid; grid-template-columns: 220px 1fr; flex: 1; }
nav.side {
  background: #fff; border-right: 1px solid #e2e8f0; padding: 1rem 0.75rem;
  display: flex; flex-direction: column; gap: 0.35rem;
}
nav.side button {
  text-align: left; background: transparent; color: #0f172a; border: none;
  padding: 0.55rem 0.75rem; border-radius: 8px; cursor: pointer;
}
nav.side button.active, nav.side button:hover { background: #ccfbf1; color: #115e59; }
main { padding: 1rem 1.25rem 2rem; }
.panel {
  background: white; border: 1px solid #e2e8f0; border-radius: 12px;
  padding: 1rem; margin-bottom: 1rem; box-shadow: 0 1px 2px rgba(15,23,42,0.04);
}
.panel h2, .panel h3 { margin-top: 0; }
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
@media (max-width: 900px) {
  .layout { grid-template-columns: 1fr; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  nav.side { flex-direction: row; flex-wrap: wrap; }
}
label { display: block; font-size: 0.85rem; color: #475569; margin-bottom: 0.25rem; }
input, select, textarea {
  width: 100%; padding: 0.5rem 0.65rem; border: 1px solid #cbd5e1;
  border-radius: 8px; background: #fff; margin-bottom: 0.75rem;
}
.form-actions { display: flex; gap: 0.5rem; flex-wrap: wrap; }
.error {
  background: #fef2f2; color: #b91c1c; border: 1px solid #fecaca;
  padding: 0.65rem 0.8rem; border-radius: 8px; margin-bottom: 0.75rem;
}
.success {
  background: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;
  padding: 0.65rem 0.8rem; border-radius: 8px; margin-bottom: 0.75rem;
}
.muted { color: #64748b; font-size: 0.9rem; }
.badge {
  display: inline-block; padding: 0.15rem 0.5rem; border-radius: 999px;
  font-size: 0.75rem; background: #e2e8f0; color: #334155;
}
.badge.ok { background: #ccfbf1; color: #0f766e; }
.badge.warn { background: #fef3c7; color: #b45309; }
.badge.bad { background: #fee2e2; color: #b91c1c; }
.badge.stale { background: #ffedd5; color: #c2410c; }
.table { width: 100%; border-collapse: collapse; font-size: 0.92rem; }
.table th, .table td { text-align: left; padding: 0.5rem 0.4rem; border-bottom: 1px solid #e2e8f0; vertical-align: top; }
.table tr:hover { background: #f8fafc; cursor: pointer; }
.login-wrap {
  min-height: 100vh; display: grid; place-items: center; padding: 1rem;
  background: linear-gradient(160deg, #0f766e 0%, #134e4a 40%, #0f172a 100%);
}
.login-card {
  width: min(420px, 100%); background: white; border-radius: 16px; padding: 1.5rem;
  box-shadow: 0 20px 50px rgba(0,0,0,0.25);
}
.login-card h1 { margin-top: 0; font-size: 1.35rem; }
.map-box {
  height: 360px; border-radius: 12px; overflow: hidden; border: 1px solid #e2e8f0;
  background: #e2e8f0;
}
.timeline { list-style: none; padding: 0; margin: 0; }
.timeline li {
  border-left: 3px solid #14b8a6; padding: 0.4rem 0.75rem; margin-left: 0.4rem;
  margin-bottom: 0.4rem; background: #f8fafc; border-radius: 0 8px 8px 0;
}
.stack { display: flex; flex-direction: column; gap: 0.75rem; }
.chips { display: flex; flex-wrap: wrap; gap: 0.4rem; }
.chip { background: #e2e8f0; border-radius: 999px; padding: 0.2rem 0.6rem; font-size: 0.8rem; }
.role-select {
  background: white; color: #0f172a; border-radius: 8px; border: none; padding: 0.35rem 0.5rem;
}
.card-list { display: flex; flex-direction: column; gap: 0.6rem; }
.work-card {
  border: 1px solid #e2e8f0; border-radius: 10px; padding: 0.75rem; background: #f8fafc;
}
.work-card header { display: flex; justify-content: space-between; gap: 0.5rem; margin-bottom: 0.35rem; }
.monitor-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 0.75rem; }
.stat { font-size: 1.4rem; font-weight: 700; color: #0f766e; }
.empty { color: #94a3b8; font-style: italic; padding: 0.5rem 0; }

