action.file_text:
const TOKEN_KEY = 'lab_session_token'
const USER_KEY = 'lab_session_user'

export type SessionUser = {
  sessionToken: string
  userId: string
  roles: string[]
  activeRole: string
  username?: string
  fullName?: string
}

export function getToken(): string | null {
  return localStorage.getItem(TOKEN_KEY)
}

export function getStoredUser(): SessionUser | null {
  const raw = localStorage.getItem(USER_KEY)
  if (!raw) return null
  try { return JSON.parse(raw) } catch { return null }
}

export function saveSession(u: SessionUser) {
  localStorage.setItem(TOKEN_KEY, u.sessionToken)
  localStorage.setItem(USER_KEY, JSON.stringify(u))
}

export function clearSession() {
  localStorage.removeItem(TOKEN_KEY)
  localStorage.removeItem(USER_KEY)
}

export class ApiError extends Error {
  status: number
  code: string
  constructor(status: number, code: string, message: string) {
    super(message)
    this.status = status
    this.code = code
  }
}

export async function api<T = any>(path: string, opts: RequestInit = {}): Promise<T> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...(opts.headers as any || {}),
  }
  const token = getToken()
  if (token) headers['Authorization'] = `Bearer ${token}`
  const res = await fetch(path.startsWith('/api') ? path : `/api${path}`, {
    ...opts,
    headers,
  })
  const text = await res.text()
  let body: any = null
  try { body = text ? JSON.parse(text) : null } catch { body = { error: text } }
  if (!res.ok) {
    throw new ApiError(res.status, body?.code || 'error', body?.error || body?.message || res.statusText)
  }
  return body?.data !== undefined ? body.data : body
}

export const AuthAPI = {
  login: (username: string, password: string) =>
    api<SessionUser>('/api/authenticate-user', { method: 'POST', body: JSON.stringify({ username, password }) }),
  selectRole: (role: string) =>
    api<{ activeRole: string; roles: string[] }>('/api/select-active-role', { method: 'POST', body: JSON.stringify({ role }) }),
  bootstrap: () => api<any>('/api/ui/bootstrap'),
}

export const OpsAPI = {
  listWork: (role?: string) => api<any>('/api/list-role-work', { method: 'POST', body: JSON.stringify(role ? { role } : {}) }),
  operations: (filters?: any) => api<any>('/api/read-operations-state', { method: 'POST', body: JSON.stringify({ filters: filters || {} }) }),
  audit: (q: any) => api<any>('/api/search-audit-trail', { method: 'POST', body: JSON.stringify(q) }),
  sampleState: (sampleId: string) => api<any>(`/api/read-sample-state/${sampleId}`),
  sampleLifecycle: (sampleId: string) => api<any>('/api/read-sample-lifecycle', { method: 'POST', body: JSON.stringify({ sampleId }) }),
  journey: (journeyId: string) => api<any>('/api/read-journey-plan', { method: 'POST', body: JSON.stringify({ journeyId }) }),
  checkServiceability: (body: any) => api<any>('/api/check-serviceability', { method: 'POST', body: JSON.stringify(body) }),
  createRequest: (body: any) => api<any>('/api/create-collection-request', { method: 'POST', body: JSON.stringify(body) }),
  accept: (assignmentId: string, idempotencyKey: string) =>
    api<any>('/api/accept-assignment', { method: 'POST', body: JSON.stringify({ assignmentId, idempotencyKey }) }),
  decline: (assignmentId: string, idempotencyKey: string) =>
    api<any>('/api/decline-assignment', { method: 'POST', body: JSON.stringify({ assignmentId, idempotencyKey }) }),
  collect: (body: any) => api<any>('/api/collect-and-seal-sample', { method: 'POST', body: JSON.stringify(body) }),
  location: (body: any) => api<any>('/api/record-worker-location', { method: 'POST', body: JSON.stringify(body) }),
  capacity: (body: any) => api<any>('/api/configure-capacity', { method: 'POST', body: JSON.stringify(body) }),
  snapshot: () => api<any>('/api/read-serviceability-snapshot', { method: 'POST', body: JSON.stringify({}) }),
}

