  const routes = ops?.connections || ops?.routes || []
  const exceptions = ops?.exceptions || samples.filter((s: any) => s.exception)

  return (
    <div className="stack">
      <div className="panel">
        <div style={{ display: 'flex', justifyContent: 'space-between' }}>
