          <div className="panel"><div className="muted">Samples</div><div className="stat">{samples.length}</div></div>
          <div className="panel"><div className="muted">Workers</div><div className="stat">{workers.length}</div></div>
          <div className="panel"><div className="muted">Nodes</div><div className="stat">{locations.length}</div></div>
          <div className="panel"><div className="muted">Laboratories</div><div className="stat">{Array.isArray(labs) ? labs.length : 0}</div></div>
          <div className="panel"><div className="muted">Routes</div><div className="stat">{routes.length}</div></div>
          <div className="panel"><div className="muted">Exceptions</div><div className="stat">{exceptions.length}</div></div>
