function WorkView({ work, role, onRefresh, onOpenSample, onAccept, onDecline }: any) {
  const current = work?.current || work?.currentWork || work?.items || []
  const past = work?.past || work?.pastWork || work?.completed || []
  const currentList = Array.isArray(current) ? current : (current.assignments || current.samples || [])
  const pastList = Array.isArray(past) ? past : (past.assignments || past.samples || [])

  function renderItem(item: any, done = false) {
    const id = item.assignmentId || item.sampleId || item.id || item.workItemId
    const title = item.title || item.assignmentType || item.status || 'Work item'
    const sampleId = item.sampleId || item.sample_id
    return (
      <div className="work-card" key={id || Math.random()}>
        <header>
          <strong>{title}</strong>
          <span className={`badge ${done ? 'ok' : 'warn'}`}>{item.status || (done ? 'completed' : 'current')}</span>
        </header>
        <div className="muted">
          {item.assignmentId && <div>Assignment: {item.assignmentId}</div>}
          {sampleId && <div>Sample: {sampleId}</div>}
          {item.locationName && <div>Location: {item.locationName}</div>}
          {item.offeredTo && <div>Offered to: {item.offeredTo}</div>}
        </div>
        <div className="form-actions" style={{ marginTop: 8 }}>
          {sampleId && <button type="button" className="secondary" onClick={() => onOpenSample(sampleId)}>Open sample</button>}
          {!done && item.assignmentId && (item.status === 'offered' || item.canAccept) && (
            <>
              <button type="button" onClick={() => onAccept(item.assignmentId)} aria-label="Accept assignment">Accept</button>
              <button type="button" className="secondary" onClick={() => onDecline(item.assignmentId)} aria-label="Decline assignment">Decline</button>
            </>
          )}
        </div>
      </div>
    )
  }

  // Also flatten RoleWork shape
  const currentItems = useMemo(() => {
    if (!work) return []
    if (Array.isArray(work)) return work
    const out: any[] = []
    const pushAll = (x: any) => {
      if (!x) return
      if (Array.isArray(x)) out.push(...x)
      else if (typeof x === 'object') {
        for (const k of ['assignments', 'samples', 'journeys', 'items', 'current', 'offered', 'active']) {
          if (Array.isArray(x[k])) out.push(...x[k])
        }
        if (x.assignmentId || x.sampleId) out.push(x)
      }
    }
    pushAll(work.current)
    pushAll(work.currentWork)
    pushAll(work.offered)
    pushAll(work.active)
    pushAll(work.items)
    if (out.length === 0 && work.assignments) pushAll(work.assignments)
    return out
  }, [work])

  const pastItems = useMemo(() => {
    if (!work) return []
    const out: any[] = []
    const src = work.past || work.pastWork || work.completed || []
    if (Array.isArray(src)) return src
    if (src.assignments) return src.assignments
    if (src.items) return src.items
    return out
  }, [work])

  return (
    <div className="stack">
      <div className="panel">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2>Current work — {roleLabel(role)}</h2>
          <button type="button" className="secondary" onClick={onRefresh}>Refresh</button>
        </div>
        <p className="muted">Assignments and samples you are responsible for in the selected role.</p>
        <div className="card-list" aria-label="Current work">
          {currentItems.length === 0 && <div className="empty">No current work</div>}
          {currentItems.map((it: any, i: number) => renderItem(it, false) || <div key={i} />)}
        </div>
      </div>
      <div className="panel">
        <h2>Past work</h2>
        <div className="card-list" aria-label="Past work">
          {pastItems.length === 0 && <div className="empty">No completed work yet</div>}
          {pastItems.map((it: any, i: number) => (
            <div key={it.assignmentId || it.sampleId || i}>{renderItem(it, true)}</div>
          ))}
        </div>
      </div>
    </div>
  )
}

function RequestForm({ userId, sampleTypes, onCreated, onError }: any) {
  const [originType, setOriginType] = useState('home')
  const [lat, setLat] = useState('51.5074')
  const [lng, setLng] = useState('-0.1278')
  const [sampleTypeId, setSampleTypeId] = useState('')
  const [deadline, setDeadline] = useState(() => new Date(Date.now() + 6 * 3600e3).toISOString().slice(0, 16))
  const [earliest, setEarliest] = useState(() => new Date().toISOString().slice(0, 16))
  const [latest, setLatest] = useState(() => new Date(Date.now() + 2 * 3600e3).toISOString().slice(0, 16))
  const [container, setContainer] = useState('standard')
  const [tmin, setTmin] = useState('2')
  const [tmax, setTmax] = useState('25')
  const [formError, setFormError] = useState('')

  useEffect(() => {
    if (!sampleTypeId && sampleTypes?.length) setSampleTypeId(sampleTypes[0].sampleTypeId || sampleTypes[0].id)
  }, [sampleTypes])

  async function submit(e: React.FormEvent) {
    e.preventDefault()
    setFormError('')
    if (!sampleTypeId) {
      setFormError('Sample type is required')
      onError('Sample type is required')
      return
    }
    if (!lat || !lng) {
      setFormError('Origin coordinates are required')
      onError('Origin coordinates are required')
      return
    }
    try {
      const body = {
        requesterId: userId,
        origin: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
        originType,
        requestedAt: nowIso(),
        deliveryDeadline: new Date(deadline).toISOString(),
        earliestCollectionAt: new Date(earliest).toISOString(),
        latestCollectionAt: new Date(latest).toISOString(),
        sampleTypeId,
        containerType: container,
        temperatureMinC: parseFloat(tmin),
        temperatureMaxC: parseFloat(tmax),
        incompatibleSampleTypes: [],
        idempotencyKey: uid(),
      }
      const res = await OpsAPI.createRequest(body)
      onCreated(res)
    } catch (err: any) {
      setFormError(err.message || 'Could not create request')
      onError(err.message || 'Could not create request')
    }
  }

  return (
    <div className="panel">
      <h2>Create collection request</h2>
      {formError && <div className="error" role="alert">{formError}</div>}
      <form aria-label="Create collection request" onSubmit={submit}>
        <div className="grid-2">
          <div>
            <label htmlFor="originType">Origin type</label>
            <select id="originType" value={originType} onChange={e => setOriginType(e.target.value)}>
              <option value="home">Home</option>
              <option value="clinic">Clinic</option>
              <option value="node">Network node</option>
            </select>
          </div>
          <div>
            <label htmlFor="sampleType">Sample type</label>
            <select id="sampleType" aria-label="Sample type" value={sampleTypeId} onChange={e => setSampleTypeId(e.target.value)} required>
              <option value="">Select…</option>
              {(sampleTypes || []).map((t: any) => (
                <option key={t.sampleTypeId || t.id} value={t.sampleTypeId || t.id}>{t.name}</option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="lat">Latitude</label>
            <input id="lat" value={lat} onChange={e => setLat(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="lng">Longitude</label>
            <input id="lng" value={lng} onChange={e => setLng(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="earliest">Earliest collection</label>
            <input id="earliest" type="datetime-local" value={earliest} onChange={e => setEarliest(e.target.value)} />
          </div>
          <div>
            <label htmlFor="latest">Latest collection</label>
            <input id="latest" type="datetime-local" value={latest} onChange={e => setLatest(e.target.value)} />
          </div>
          <div>
            <label htmlFor="deadline">Delivery deadline</label>
            <input id="deadline" type="datetime-local" value={deadline} onChange={e => setDeadline(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="container">Container type</label>
            <input id="container" value={container} onChange={e => setContainer(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="tmin">Temp min °C</label>
            <input id="tmin" value={tmin} onChange={e => setTmin(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="tmax">Temp max °C</label>
            <input id="tmax" value={tmax} onChange={e => setTmax(e.target.value)} required />
          </div>
        </div>
        <div className="form-actions">
          <button type="submit">Create request</button>
        </div>
      </form>
    </div>
  )
}

function ServiceabilityForm({ sampleTypes, onError }: any) {
  const [lat, setLat] = useState('51.5074')
  const [lng, setLng] = useState('-0.1278')
  const [sampleTypeId, setSampleTypeId] = useState('')
  const [deadline, setDeadline] = useState(() => new Date(Date.now() + 6 * 3600e3).toISOString().slice(0, 16))
  const [result, setResult] = useState<any>(null)

  useEffect(() => {
    if (!sampleTypeId && sampleTypes?.length) setSampleTypeId(sampleTypes[0].sampleTypeId || sampleTypes[0].id)
  }, [sampleTypes])

  async function run(e: React.FormEvent) {
    e.preventDefault()
    setResult(null)
    try {
      const res = await OpsAPI.checkServiceability({
        origin: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
        originType: 'home',
        sampleTypeId,
        requestedAt: nowIso(),
        deliveryDeadline: new Date(deadline).toISOString(),
        earliestCollectionAt: nowIso(),
        latestCollectionAt: new Date(Date.now() + 2 * 3600e3).toISOString(),
      })
      setResult(res)
    } catch (err: any) {
      onError(err.message)
    }
  }

  return (
    <div className="panel">
      <h2>Serviceability check</h2>
      <p className="muted">Dry run — does not create a request, sample, journey, assignment, or capacity reservation.</p>
      <form aria-label="Serviceability check" onSubmit={run}>
        <div className="grid-2">
          <div>
            <label htmlFor="s-lat">Latitude</label>
            <input id="s-lat" value={lat} onChange={e => setLat(e.target.value)} />
          </div>
          <div>
            <label htmlFor="s-lng">Longitude</label>
            <input id="s-lng" value={lng} onChange={e => setLng(e.target.value)} />
          </div>
          <div>
            <label htmlFor="s-type">Sample type</label>
            <select id="s-type" value={sampleTypeId} onChange={e => setSampleTypeId(e.target.value)}>
              {(sampleTypes || []).map((t: any) => (
                <option key={t.sampleTypeId || t.id} value={t.sampleTypeId || t.id}>{t.name}</option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="s-deadline">Delivery deadline</label>
            <input id="s-deadline" type="datetime-local" value={deadline} onChange={e => setDeadline(e.target.value)} />
          </div>
        </div>
        <button type="submit">Check serviceability</button>
      </form>
      {result && (
        <div style={{ marginTop: 12 }} aria-label="Serviceability result">
          <span className={`badge ${result.serviceable ? 'ok' : 'bad'}`}>
            {result.serviceable ? 'Serviceable' : 'Not serviceable'}
          </span>
          <p>{result.reason}</p>
          <p className="muted">Version: {result.serviceabilityVersion}</p>
          {result.targetLaboratoryId && <p>Target lab: {result.targetLaboratoryId}</p>}
          {result.estimatedArrivalAt && <p>ETA: {result.estimatedArrivalAt}</p>}
        </div>
      )}
    </div>
  )
}

function SampleView({ sampleId, sample, lifecycle, onLoad, setSampleId }: any) {
  const history = lifecycle?.timeline || lifecycle?.history || lifecycle?.events || sample?.statusHistory || sample?.timeline || []
  const stale = sample?.locationStale || sample?.stale || sample?.locationIsStale
  const exception = sample?.exception || sample?.hasException
  const custodian = sample?.currentHolderId || sample?.currentCustodianId || sample?.custodianId || sample?.currentHolder
  const loc = sample?.latestLocation || sample?.location || (sample?.latestLat != null ? { latitude: sample.latestLat, longitude: sample.latestLng } : null)
  const progress = sample?.routeProgress || sample?.progress || sample?.status

  return (
    <div className="stack">
      <div className="panel">
        <h2>Sample tracking</h2>
        <form
          onSubmit={e => { e.preventDefault(); onLoad(sampleId) }}
          style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}
          aria-label="Load sample"
        >
          <input
            aria-label="Sample id"
            placeholder="Sample ID"
            value={sampleId}
            onChange={e => setSampleId(e.target.value)}
            style={{ flex: 1, marginBottom: 0 }}
          />
          <button type="submit">Load</button>
        </form>
      </div>
      {sample && (
        <>
          <div className="panel">
            <h3>Status</h3>
            <div className="chips">
              <span className="chip">Status: {sample.status || 'unknown'}</span>
              {stale ? <span className="badge stale">Location stale</span> : <span className="badge ok">Location fresh</span>}
              {exception ? <span className="badge bad" aria-label="Exception flag">Exception</span> : <span className="badge ok">No exception</span>}
            </div>
            <p><strong>Custodian:</strong> {custodian || '—'}</p>
            <p><strong>Route progress:</strong> {typeof progress === 'object' ? JSON.stringify(progress) : (progress || '—')}</p>
            <p><strong>Last update:</strong> {sample.locationRecordedAt || sample.lastUpdateAt || sample.updatedAt || '—'}</p>
            {loc && (
              <p><strong>Location:</strong> {loc.latitude ?? loc.lat}, {loc.longitude ?? loc.lng}</p>
            )}
            {exception && typeof exception === 'object' && (
              <div className="error" role="status">
                Exception: {exception.reason || exception.code || JSON.stringify(exception)}
              </div>
            )}
          </div>
          <div className="panel">
            <h3>Status timeline</h3>
            <ol className="timeline" aria-label="Sample status history">
              {(Array.isArray(history) ? history : []).length === 0 && <li className="empty">No history yet</li>}
              {(Array.isArray(history) ? history : []).map((h: any, i: number) => (
                <li key={h.eventId || h.id || i}>
                  <strong>{h.action || h.status || h.type || 'event'}</strong>
                  <div className="muted">{h.occurredAt || h.at || h.createdAt}</div>
                  {h.role && <div className="muted">Role: {h.role}</div>}
                </li>
              ))}
            </ol>
          </div>
          <div className="panel">
            <h3>Map</h3>
            <MapView
              markers={[
                loc ? { id: 'sample', lat: loc.latitude ?? loc.lat, lng: loc.longitude ?? loc.lng, label: 'Sample' } : null,
              ].filter(Boolean) as any}
            />
          </div>
        </>
      )}
    </div>
  )
}

