function CapacityView({ ops, bootstrap, onSaved, onError }: any) {
  const locations = ops?.locations || bootstrap?.locations || []
  const [resourceId, setResourceId] = useState('')
  const [units, setUnits] = useState('100')
  const [cooled, setCooled] = useState('50')

  useEffect(() => {
    if (!resourceId && locations[0]) setResourceId(locations[0].locationId || locations[0].id)
  }, [locations])

  async function save(e: React.FormEvent) {
    e.preventDefault()
    try {
      await OpsAPI.capacity({
        resourceId,
        capacityUnits: parseInt(units, 10),
        cooledCapacityUnits: parseInt(cooled, 10),
      })
      onSaved()
    } catch (err: any) {
      onError(err.message)
    }
  }

  const selected = locations.find((l: any) => (l.locationId || l.id) === resourceId)
  const cap = selected?.capacity || selected

  return (
    <div className="panel">
      <h2>Capacity</h2>
      <p className="muted">Configure regular and cooled capacity for your node or laboratory.</p>
      {cap && (
        <div className="chips" style={{ marginBottom: 12 }} aria-label="Current capacity">
          <span className="chip">Regular: {cap.capacityUnits ?? cap.capacity_units ?? '—'} (avail {cap.availableUnits ?? '—'})</span>
          <span className="chip">Cooled: {cap.cooledCapacityUnits ?? cap.cooled_capacity_units ?? '—'} (avail {cap.cooledAvailableUnits ?? '—'})</span>
        </div>
      )}
      <form aria-label="Configure capacity" onSubmit={save}>
        <label htmlFor="resource">Resource</label>
        <select id="resource" value={resourceId} onChange={e => setResourceId(e.target.value)}>
          {locations.map((l: any) => (
            <option key={l.locationId || l.id} value={l.locationId || l.id}>{l.name || l.locationId || l.id}</option>
          ))}
        </select>
        <label htmlFor="units">Regular capacity units</label>
        <input id="units" value={units} onChange={e => setUnits(e.target.value)} />
        <label htmlFor="cooled">Cooled capacity units</label>
        <input id="cooled" value={cooled} onChange={e => setCooled(e.target.value)} />
        <button type="submit">Save capacity</button>
      </form>
    </div>
  )
}

function LocationView({ work, onSaved, onError }: any) {
  const assignments = useMemo(() => {
    const out: any[] = []
    const walk = (x: any) => {
      if (!x) return
      if (Array.isArray(x)) x.forEach(walk)
      else if (typeof x === 'object') {
        if (x.assignmentId) out.push(x)
        Object.values(x).forEach(walk)
      }
    }
    walk(work)
    return out
  }, [work])
  const [assignmentId, setAssignmentId] = useState('')
  const [lat, setLat] = useState('51.5074')
  const [lng, setLng] = useState('-0.1278')
  const [seq, setSeq] = useState('1')

  useEffect(() => {
    if (!assignmentId && assignments[0]) setAssignmentId(assignments[0].assignmentId)
  }, [assignments])

  async function save(e: React.FormEvent) {
    e.preventDefault()
    try {
      await OpsAPI.location({
        assignmentId,
        coordinate: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
        sequence: parseInt(seq, 10),
        recordedAt: nowIso(),
      })
      onSaved()
      setSeq(String(parseInt(seq, 10) + 1))
    } catch (err: any) {
      onError(err.message)
    }
  }

  return (
    <div className="panel">
      <h2>Record location</h2>
      <form aria-label="Record worker location" onSubmit={save}>
        <label htmlFor="asg">Assignment</label>
        <select id="asg" value={assignmentId} onChange={e => setAssignmentId(e.target.value)} required>
          <option value="">Select assignment…</option>
          {assignments.map((a: any) => (
            <option key={a.assignmentId} value={a.assignmentId}>{a.assignmentId} ({a.status || a.assignmentType || 'work'})</option>
          ))}
        </select>
        <div className="grid-2">
          <div>
            <label htmlFor="wlat">Latitude</label>
            <input id="wlat" value={lat} onChange={e => setLat(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="wlng">Longitude</label>
            <input id="wlng" value={lng} onChange={e => setLng(e.target.value)} required />
          </div>
        </div>
        <label htmlFor="seq">Sequence</label>
        <input id="seq" value={seq} onChange={e => setSeq(e.target.value)} required />
        <button type="submit">Record location</button>
      </form>
    </div>
  )
}

function AdminView({ bootstrap, ops, onRefresh, onError, onNotice }: any) {
  return (
    <div className="stack">
      <div className="panel">
        <h2>Administrator</h2>
        <p className="muted">Manage network configuration via API. Sample types and bootstrap data are shown below.</p>
        <button type="button" className="secondary" onClick={onRefresh}>Refresh bootstrap</button>
      </div>
      <div className="panel">
        <h3>Sample types</h3>
        <ul>
          {(bootstrap?.sampleTypes || ops?.sampleTypes || []).map((t: any) => (
            <li key={t.sampleTypeId || t.id}>{t.name} — {t.containerType || t.container_type}</li>
          ))}
        </ul>
      </div>
      <div className="panel">
        <h3>Locations</h3>
        <ul>
          {(ops?.locations || []).map((l: any) => (
            <li key={l.locationId || l.id}>{l.name} ({l.active ? 'active' : 'inactive'})</li>
          ))}
        </ul>
      </div>
    </div>
  )
}
"}

