import React, { useCallback, useEffect, useMemo, useState } from 'react'
import {
  ApiError, AuthAPI, OpsAPI, SessionUser, clearSession, getStoredUser, saveSession,
} from './api/client'
import MapView from './components/MapView'

type View =
  | 'work'
  | 'requests'
  | 'serviceability'
  | 'sample'
  | 'monitor'
  | 'audit'
  | 'capacity'
  | 'location'
  | 'admin'

const ROLE_LABELS: Record<string, string> = {
  administrator: 'Administrator',
  dispatcher: 'Dispatcher',
  requester: 'Requester',
  collection_professional: 'Collection professional',
  delivery_partner: 'Relay courier',
  node_handler: 'Node handler',
  laboratory_team: 'Laboratory intake',
}

function roleLabel(r: string) {
  return ROLE_LABELS[r] || r
}

function nowIso() {
  return new Date().toISOString()
}

function uid() {
  return crypto.randomUUID()
}

export default function App() {
  const [user, setUser] = useState<SessionUser | null>(getStoredUser())
  const [view, setView] = useState<View>('work')
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [bootstrap, setBootstrap] = useState<any>(null)
  const [work, setWork] = useState<any>(null)
  const [ops, setOps] = useState<any>(null)
  const [audit, setAudit] = useState<any>(null)
  const [auditQuery, setAuditQuery] = useState('')
  const [sampleId, setSampleId] = useState('')
  const [sample, setSample] = useState<any>(null)
  const [lifecycle, setLifecycle] = useState<any>(null)
  const [busy, setBusy] = useState(false)

  const activeRole = user?.activeRole || ''

  const refreshBootstrap = useCallback(async () => {
    if (!user) return
    try {
      const data = await AuthAPI.bootstrap()
      setBootstrap(data)
      if (data?.user) {
        const next = {
          ...user,
          roles: data.user.roles || user.roles,
          activeRole: data.user.activeRole || user.activeRole,
          fullName: data.user.fullName || user.fullName,
          username: data.user.username || user.username,
          userId: data.user.userId || user.userId,
        }
        setUser(next)
        saveSession(next)
      }
    } catch (e: any) {
      if (e instanceof ApiError && e.status === 401) {
        clearSession()
        setUser(null)
      }
    }
  }, [user])

  const refreshWork = useCallback(async () => {
    if (!user) return
    try {
      const data = await OpsAPI.listWork(user.activeRole || undefined)
      setWork(data)
    } catch (e: any) {
      setError(e.message || 'Failed to load work')
    }
  }, [user])

  const refreshOps = useCallback(async () => {
    if (!user) return
    try {
      const data = await OpsAPI.operations({})
      setOps(data)
    } catch (e: any) {
      /* ignore if forbidden */
    }
  }, [user])

  useEffect(() => {
    if (!user) return
    refreshBootstrap()
    refreshWork()
    refreshOps()
  }, [user?.sessionToken, user?.activeRole])

  async function handleLogin(username: string, password: string) {
    setError('')
    setBusy(true)
    try {
      const data = await AuthAPI.login(username, password)
      const session: SessionUser = {
        sessionToken: data.sessionToken,
        userId: data.userId,
        roles: data.roles || [],
        activeRole: data.activeRole || (data.roles?.[0] || ''),
        username,
      }
      saveSession(session)
      setUser(session)
      setView('work')
      setNotice('Signed in')
    } catch (e: any) {
      setError(e.message || 'Invalid credentials')
    } finally {
      setBusy(false)
    }
  }

  async function handleLogout() {
    clearSession()
    setUser(null)
    setBootstrap(null)
    setWork(null)
    setOps(null)
    setSample(null)
    setNotice('Signed out')
  }

  async function handleRoleChange(role: string) {
    setError('')
    try {
      const data = await AuthAPI.selectRole(role)
      if (!user) return
      const next = { ...user, activeRole: data.activeRole || role, roles: data.roles || user.roles }
      saveSession(next)
      setUser(next)
      setNotice(`Working as ${roleLabel(role)}`)
      await refreshWork()
    } catch (e: any) {
      setError(e.message || 'Could not switch role')
    }
  }

  async function loadSample(id: string) {
    if (!id) return
    setError('')
    setSampleId(id)
    try {
      const [st, life] = await Promise.all([
        OpsAPI.sampleState(id),
        OpsAPI.sampleLifecycle(id),
      ])
      setSample(st)
      setLifecycle(life)
      setView('sample')
    } catch (e: any) {
      setError(e.message || 'Sample not found')
    }
  }

  async function searchAudit(q = auditQuery) {
    setError('')
    try {
      const data = await OpsAPI.audit({
        query: q || undefined,
        limit: 50,
        order: 'desc',
      })
      setAudit(data)
      setView('audit')
    } catch (e: any) {
      setError(e.message || 'Audit search failed')
    }
  }

  if (!user) {
    return <LoginPage onLogin={handleLogin} error={error} busy={busy} />
  }

  const nav: { id: View; label: string; roles?: string[] }[] = [
    { id: 'work', label: 'My work' },
    { id: 'requests', label: 'New request', roles: ['requester', 'administrator'] },
    { id: 'serviceability', label: 'Serviceability', roles: ['requester', 'dispatcher', 'administrator'] },
    { id: 'sample', label: 'Sample tracking' },
    { id: 'monitor', label: 'Operations', roles: ['dispatcher', 'administrator'] },
    { id: 'audit', label: 'Audit', roles: ['dispatcher', 'administrator'] },
    { id: 'capacity', label: 'Capacity', roles: ['node_handler', 'laboratory_team', 'administrator', 'dispatcher'] },
    { id: 'location', label: 'My location', roles: ['collection_professional', 'delivery_partner', 'node_handler', 'laboratory_team'] },
    { id: 'admin', label: 'Admin', roles: ['administrator'] },
  ]

  const visibleNav = nav.filter(n => !n.roles || n.roles.includes(activeRole) || activeRole === 'administrator')

  return (
    <div className="app-shell">
      <header className="topbar">
        <h1>Lab Sample Pickup & Delivery</h1>
        <div className="meta">
          <span aria-label="signed-in user">{user.fullName || user.username || user.userId}</span>
          <label htmlFor="role-switch" className="muted" style={{ color: 'white' }}>Active role</label>
          <select
            id="role-switch"
            className="role-select"
            aria-label="Select active role"
            value={activeRole}
            onChange={e => handleRoleChange(e.target.value)}
          >
            {(user.roles || []).map(r => (
              <option key={r} value={r}>{roleLabel(r)}</option>
            ))}
          </select>
          <button type="button" className="secondary" onClick={handleLogout} aria-label="Sign out">Sign out</button>
        </div>
      </header>
      <div className="layout">
        <nav className="side" aria-label="Primary">
          {visibleNav.map(n => (
            <button
              key={n.id}
              type="button"
              className={view === n.id ? 'active' : ''}
              onClick={() => {
                setView(n.id)
                if (n.id === 'work') refreshWork()
                if (n.id === 'monitor') refreshOps()
                if (n.id === 'audit') searchAudit()
              }}
            >
              {n.label}
            </button>
          ))}
        </nav>
        <main>
          {error && <div className="error" role="alert">{error}</div>}
          {notice && <div className="success" role="status">{notice}</div>}

          {view === 'work' && (
            <WorkView
              work={work}
              role={activeRole}
              onRefresh={refreshWork}
              onOpenSample={loadSample}
              onAccept={async (assignmentId) => {
                setError('')
                try {
                  await OpsAPI.accept(assignmentId, uid())
                  setNotice('Assignment accepted')
                  await refreshWork()
                } catch (e: any) {
                  setError(e.message)
                }
              }}
              onDecline={async (assignmentId) => {
                setError('')
                try {
                  await OpsAPI.decline(assignmentId, uid())
                  setNotice('Assignment declined')
                  await refreshWork()
                } catch (e: any) {
                  setError(e.message)
                }
              }}
            />
          )}

          {view === 'requests' && (
            <RequestForm
              userId={user.userId}
              sampleTypes={bootstrap?.sampleTypes || ops?.sampleTypes || []}
              onCreated={(res) => {
                setNotice(`Request created: sample ${res.sampleId}`)
                if (res.sampleId) loadSample(res.sampleId)
              }}
              onError={setError}
            />
          )}

          {view === 'serviceability' && (
            <ServiceabilityForm
              sampleTypes={bootstrap?.sampleTypes || ops?.sampleTypes || []}
              onError={setError}
            />
          )}

          {view === 'sample' && (
            <SampleView
              sampleId={sampleId}
              sample={sample}
              lifecycle={lifecycle}
              onLoad={loadSample}
              setSampleId={setSampleId}
            />
          )}

          {view === 'monitor' && (
            <MonitorView ops={ops} onRefresh={refreshOps} onOpenSample={loadSample} />
          )}

          {view === 'audit' && (
            <AuditView
              audit={audit}
              query={auditQuery}
              setQuery={setAuditQuery}
              onSearch={() => searchAudit()}
            />
          )}

          {view === 'capacity' && (
            <CapacityView
              ops={ops}
              bootstrap={bootstrap}
              onSaved={() => { setNotice('Capacity updated'); refreshOps() }}
              onError={setError}
            />
          )}

          {view === 'location' && (
            <LocationView
              work={work}
              onSaved={() => setNotice('Location recorded')}
              onError={setError}
            />
          )}

          {view === 'admin' && (
            <AdminView bootstrap={bootstrap} ops={ops} onRefresh={() => { refreshBootstrap(); refreshOps() }} onError={setError} onNotice={setNotice} />
          )}
        </main>
      </div>
    </div>
  )
}

function LoginPage({ onLogin, error, busy }: { onLogin: (u: string, p: string) => void; error: string; busy: boolean }) {
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  return (
    <div className="login-wrap">
      <form
        className="login-card"
        aria-label="Sign in"
        onSubmit={e => {
          e.preventDefault()
          onLogin(username, password)
        }}
      >
        <h1>Sign in</h1>
        <p className="muted">Lab sample pickup and delivery network</p>
        {error && <div className="error" role="alert">{error}</div>}
        <label htmlFor="username">Username</label>
        <input id="username" name="username" autoComplete="username" value={username} onChange={e => setUsername(e.target.value)} required />
        <label htmlFor="password">Password</label>
        <input id="password" name="password" type="password" autoComplete="current-password" value={password} onChange={e => setPassword(e.target.value)} required />
        <div className="form-actions">
          <button type="submit" disabled={busy} aria-label="Sign in">{busy ? 'Signing in…' : 'Sign in'}</button>
        </div>
      </form>
    </div>
  )
}

function WorkView({ work, role, onRefresh, onOpenSample, onAccept, onDecline }: any) {
  const current = work?.current || work?.currentWork || work?.items || []
  const past = work?.past || work?.pastWork || work?.completed || []
  const currentList = Array.isArray(current) ? current : (current.assignments || current.samples || [])
  const pastList = Array.isArray(past) ? past : (past.assignments || past.samples || [])

  function renderItem(item: any, done = false) {
    const id = item.assignmentId || item.sampleId || item.id || item.workItemId
    const title = item.title || item.assignmentType || item.status || 'Work item'
    const sampleId = item.sampleId || item.sample_id
    return (
      <div className="work-card" key={id || Math.random()}>
        <header>
          <strong>{title}</strong>
          <span className={`badge ${done ? 'ok' : 'warn'}`}>{item.status || (done ? 'completed' : 'current')}</span>
        </header>
        <div className="muted">
          {item.assignmentId && <div>Assignment: {item.assignmentId}</div>}
          {sampleId && <div>Sample: {sampleId}</div>}
          {item.locationName && <div>Location: {item.locationName}</div>}
          {item.offeredTo && <div>Offered to: {item.offeredTo}</div>}
        </div>
        <div className="form-actions" style={{ marginTop: 8 }}>
          {sampleId && <button type="button" className="secondary" onClick={() => onOpenSample(sampleId)}>Open sample</button>}
          {!done && item.assignmentId && (item.status === 'offered' || item.canAccept) && (
            <>
              <button type="button" onClick={() => onAccept(item.assignmentId)} aria-label="Accept assignment">Accept</button>
              <button type="button" className="secondary" onClick={() => onDecline(item.assignmentId)} aria-label="Decline assignment">Decline</button>
            </>
          )}
        </div>
      </div>
    )
  }

  // Also flatten RoleWork shape
  const currentItems = useMemo(() => {
    if (!work) return []
    if (Array.isArray(work)) return work
    const out: any[] = []
    const pushAll = (x: any) => {
      if (!x) return
      if (Array.isArray(x)) out.push(...x)
      else if (typeof x === 'object') {
        for (const k of ['assignments', 'samples', 'journeys', 'items', 'current', 'offered', 'active']) {
          if (Array.isArray(x[k])) out.push(...x[k])
        }
        if (x.assignmentId || x.sampleId) out.push(x)
      }
    }
    pushAll(work.current)
    pushAll(work.currentWork)
    pushAll(work.offered)
    pushAll(work.active)
    pushAll(work.items)
    if (out.length === 0 && work.assignments) pushAll(work.assignments)
    return out
  }, [work])

  const pastItems = useMemo(() => {
    if (!work) return []
    const out: any[] = []
    const src = work.past || work.pastWork || work.completed || []
    if (Array.isArray(src)) return src
    if (src.assignments) return src.assignments
    if (src.items) return src.items
    return out
  }, [work])

  return (
    <div className="stack">
      <div className="panel">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2>Current work — {roleLabel(role)}</h2>
          <button type="button" className="secondary" onClick={onRefresh}>Refresh</button>
        </div>
        <p className="muted">Assignments and samples you are responsible for in the selected role.</p>
        <div className="card-list" aria-label="Current work">
          {currentItems.length === 0 && <div className="empty">No current work</div>}
          {currentItems.map((it: any, i: number) => renderItem(it, false) || <div key={i} />)}
        </div>
      </div>
      <div className="panel">
        <h2>Past work</h2>
        <div className="card-list" aria-label="Past work">
          {pastItems.length === 0 && <div className="empty">No completed work yet</div>}
          {pastItems.map((it: any, i: number) => (
            <div key={it.assignmentId || it.sampleId || i}>{renderItem(it, true)}</div>
          ))}
        </div>
      </div>
    </div>
  )
}

function RequestForm({ userId, sampleTypes, onCreated, onError }: any) {
  const [originType, setOriginType] = useState('home')
  const [lat, setLat] = useState('51.5074')
  const [lng, setLng] = useState('-0.1278')
  const [sampleTypeId, setSampleTypeId] = useState('')
  const [deadline, setDeadline] = useState(() => new Date(Date.now() + 6 * 3600e3).toISOString().slice(0, 16))
  const [earliest, setEarliest] = useState(() => new Date().toISOString().slice(0, 16))
  const [latest, setLatest] = useState(() => new Date(Date.now() + 2 * 3600e3).toISOString().slice(0, 16))
  const [container, setContainer] = useState('standard')
  const [tmin, setTmin] = useState('2')
  const [tmax, setTmax] = useState('25')
  const [formError, setFormError] = useState('')

  useEffect(() => {
    if (!sampleTypeId && sampleTypes?.length) setSampleTypeId(sampleTypes[0].sampleTypeId || sampleTypes[0].id)
  }, [sampleTypes])

  async function submit(e: React.FormEvent) {
    e.preventDefault()
    setFormError('')
    if (!sampleTypeId) {
      setFormError('Sample type is required')
      onError('Sample type is required')
      return
    }
    if (!lat || !lng) {
      setFormError('Origin coordinates are required')
      onError('Origin coordinates are required')
      return
    }
    try {
      const body = {
        requesterId: userId,
        origin: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
        originType,
        requestedAt: nowIso(),
        deliveryDeadline: new Date(deadline).toISOString(),
        earliestCollectionAt: new Date(earliest).toISOString(),
        latestCollectionAt: new Date(latest).toISOString(),
        sampleTypeId,
        containerType: container,
        temperatureMinC: parseFloat(tmin),
        temperatureMaxC: parseFloat(tmax),
        incompatibleSampleTypes: [],
        idempotencyKey: uid(),
      }
      const res = await OpsAPI.createRequest(body)
      onCreated(res)
    } catch (err: any) {
      setFormError(err.message || 'Could not create request')
      onError(err.message || 'Could not create request')
    }
  }

  return (
    <div className="panel">
      <h2>Create collection request</h2>
      {formError && <div className="error" role="alert">{formError}</div>}
      <form aria-label="Create collection request" onSubmit={submit}>
        <div className="grid-2">
          <div>
            <label htmlFor="originType">Origin type</label>
            <select id="originType" value={originType} onChange={e => setOriginType(e.target.value)}>
              <option value="home">Home</option>
              <option value="clinic">Clinic</option>
              <option value="node">Network node</option>
            </select>
          </div>
          <div>
            <label htmlFor="sampleType">Sample type</label>
            <select id="sampleType" aria-label="Sample type" value={sampleTypeId} onChange={e => setSampleTypeId(e.target.value)} required>
              <option value="">Select…</option>
              {(sampleTypes || []).map((t: any) => (
                <option key={t.sampleTypeId || t.id} value={t.sampleTypeId || t.id}>{t.name}</option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="lat">Latitude</label>
            <input id="lat" value={lat} onChange={e => setLat(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="lng">Longitude</label>
            <input id="lng" value={lng} onChange={e => setLng(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="earliest">Earliest collection</label>
            <input id="earliest" type="datetime-local" value={earliest} onChange={e => setEarliest(e.target.value)} />
          </div>
          <div>
            <label htmlFor="latest">Latest collection</label>
            <input id="latest" type="datetime-local" value={latest} onChange={e => setLatest(e.target.value)} />
          </div>
          <div>
            <label htmlFor="deadline">Delivery deadline</label>
            <input id="deadline" type="datetime-local" value={deadline} onChange={e => setDeadline(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="container">Container type</label>
            <input id="container" value={container} onChange={e => setContainer(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="tmin">Temp min °C</label>
            <input id="tmin" value={tmin} onChange={e => setTmin(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="tmax">Temp max °C</label>
            <input id="tmax" value={tmax} onChange={e => setTmax(e.target.value)} required />
          </div>
        </div>
        <div className="form-actions">
          <button type="submit">Create request</button>
        </div>
      </form>
    </div>
  )
}

function ServiceabilityForm({ sampleTypes, onError }: any) {
  const [lat, setLat] = useState('51.5074')
  const [lng, setLng] = useState('-0.1278')
  const [sampleTypeId, setSampleTypeId] = useState('')
  const [deadline, setDeadline] = useState(() => new Date(Date.now() + 6 * 3600e3).toISOString().slice(0, 16))
  const [result, setResult] = useState<any>(null)

  useEffect(() => {
    if (!sampleTypeId && sampleTypes?.length) setSampleTypeId(sampleTypes[0].sampleTypeId || sampleTypes[0].id)
  }, [sampleTypes])

  async function run(e: React.FormEvent) {
    e.preventDefault()
    setResult(null)
    try {
      const res = await OpsAPI.checkServiceability({
        origin: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
        originType: 'home',
        sampleTypeId,
        requestedAt: nowIso(),
        deliveryDeadline: new Date(deadline).toISOString(),
        earliestCollectionAt: nowIso(),
        latestCollectionAt: new Date(Date.now() + 2 * 3600e3).toISOString(),
      })
      setResult(res)
    } catch (err: any) {
      onError(err.message)
    }
  }

  return (
    <div className="panel">
      <h2>Serviceability check</h2>
      <p className="muted">Dry run — does not create a request, sample, journey, assignment, or capacity reservation.</p>
      <form aria-label="Serviceability check" onSubmit={run}>
        <div className="grid-2">
          <div>
            <label htmlFor="s-lat">Latitude</label>
            <input id="s-lat" value={lat} onChange={e => setLat(e.target.value)} />
          </div>
          <div>
            <label htmlFor="s-lng">Longitude</label>
            <input id="s-lng" value={lng} onChange={e => setLng(e.target.value)} />
          </div>
          <div>
            <label htmlFor="s-type">Sample type</label>
            <select id="s-type" value={sampleTypeId} onChange={e => setSampleTypeId(e.target.value)}>
              {(sampleTypes || []).map((t: any) => (
                <option key={t.sampleTypeId || t.id} value={t.sampleTypeId || t.id}>{t.name}</option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="s-deadline">Delivery deadline</label>
            <input id="s-deadline" type="datetime-local" value={deadline} onChange={e => setDeadline(e.target.value)} />
          </div>
        </div>
        <button type="submit">Check serviceability</button>
      </form>
      {result && (
        <div style={{ marginTop: 12 }} aria-label="Serviceability result">
          <span className={`badge ${result.serviceable ? 'ok' : 'bad'}`}>
            {result.serviceable ? 'Serviceable' : 'Not serviceable'}
          </span>
          <p>{result.reason}</p>
          <p className="muted">Version: {result.serviceabilityVersion}</p>
          {result.targetLaboratoryId && <p>Target lab: {result.targetLaboratoryId}</p>}
          {result.estimatedArrivalAt && <p>ETA: {result.estimatedArrivalAt}</p>}
        </div>
      )}
    </div>
  )
}

function SampleView({ sampleId, sample, lifecycle, onLoad, setSampleId }: any) {
  const history = lifecycle?.timeline || lifecycle?.history || lifecycle?.events || sample?.statusHistory || sample?.timeline || []
  const stale = sample?.locationStale || sample?.stale || sample?.locationIsStale
  const exception = sample?.exception || sample?.hasException
  const custodian = sample?.currentHolderId || sample?.currentCustodianId || sample?.custodianId || sample?.currentHolder
  const loc = sample?.latestLocation || sample?.location || (sample?.latestLat != null ? { latitude: sample.latestLat, longitude: sample.latestLng } : null)
  const progress = sample?.routeProgress || sample?.progress || sample?.status

  return (
    <div className="stack">
      <div className="panel">
        <h2>Sample tracking</h2>
        <form
          onSubmit={e => { e.preventDefault(); onLoad(sampleId) }}
          style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}
          aria-label="Load sample"
        >
          <input
            aria-label="Sample id"
            placeholder="Sample ID"
            value={sampleId}
            onChange={e => setSampleId(e.target.value)}
            style={{ flex: 1, marginBottom: 0 }}
          />
          <button type="submit">Load</button>
        </form>
      </div>
      {sample && (
        <>
          <div className="panel">
            <h3>Status</h3>
            <div className="chips">
              <span className="chip">Status: {sample.status || 'unknown'}</span>
              {stale ? <span className="badge stale">Location stale</span> : <span className="badge ok">Location fresh</span>}
              {exception ? <span className="badge bad" aria-label="Exception flag">Exception</span> : <span className="badge ok">No exception</span>}
            </div>
            <p><strong>Custodian:</strong> {custodian || '—'}</p>
            <p><strong>Route progress:</strong> {typeof progress === 'object' ? JSON.stringify(progress) : (progress || '—')}</p>
            <p><strong>Last update:</strong> {sample.locationRecordedAt || sample.lastUpdateAt || sample.updatedAt || '—'}</p>
            {loc && (
              <p><strong>Location:</strong> {loc.latitude ?? loc.lat}, {loc.longitude ?? loc.lng}</p>
            )}
            {exception && typeof exception === 'object' && (
              <div className="error" role="status">
                Exception: {exception.reason || exception.code || JSON.stringify(exception)}
              </div>
            )}
          </div>
          <div className="panel">
            <h3>Status timeline</h3>
            <ol className="timeline" aria-label="Sample status history">
              {(Array.isArray(history) ? history : []).length === 0 && <li className="empty">No history yet</li>}
              {(Array.isArray(history) ? history : []).map((h: any, i: number) => (
                <li key={h.eventId || h.id || i}>
                  <strong>{h.action || h.status || h.type || 'event'}</strong>
                  <div className="muted">{h.occurredAt || h.at || h.createdAt}</div>
                  {h.role && <div className="muted">Role: {h.role}</div>}
                </li>
              ))}
            </ol>
          </div>
          <div className="panel">
            <h3>Map</h3>
            <MapView
              markers={[
                loc ? { id: 'sample', lat: loc.latitude ?? loc.lat, lng: loc.longitude ?? loc.lng, label: 'Sample' } : null,
              ].filter(Boolean) as any}
            />
          </div>
        </>
      )}
    </div>
  )
}

function MonitorView({ ops, onRefresh, onOpenSample }: any) {
  const samples = ops?.samples || ops?.activeSamples || []
  const workers = ops?.workers || []
  const locations = ops?.locations || ops?.nodes || []
  const labs = ops?.laboratories || locations.filter((l: any) => l.functions?.laboratory || l.fn_laboratory)
  const routes = ops?.connections || ops?.routes || []
  const exceptions = ops?.exceptions || samples.filter((s: any) => s.exception)

  return (
    <div className="stack">
      <div className="panel">
        <div style={{ display: 'flex', justifyContent: 'space-between' }}>
          <h2>Operations monitor</h2>
          <button type="button" className="secondary" onClick={onRefresh}>Refresh</button>
        </div>
        <div className="monitor-grid" aria-label="Monitor categories">
          <div className="panel"><div className="muted">Samples</div><div className="stat">{samples.length}</div></div>
          <div className="panel"><div className="muted">Workers</div><div className="stat">{workers.length}</div></div>
          <div className="panel"><div className="muted">Nodes</div><div className="stat">{locations.length}</div></div>
          <div className="panel"><div className="muted">Laboratories</div><div className="stat">{Array.isArray(labs) ? labs.length : 0}</div></div>
          <div className="panel"><div className="muted">Routes</div><div className="stat">{routes.length}</div></div>
          <div className="panel"><div className="muted">Exceptions</div><div className="stat">{exceptions.length}</div></div>
        </div>
      </div>
      <div className="panel">
        <h3>Live map</h3>
        <MapView
          markers={[
            ...locations.map((l: any) => ({
              id: l.locationId || l.id,
              lat: l.coordinate?.latitude ?? l.latitude,
              lng: l.coordinate?.longitude ?? l.longitude,
              label: l.name,
            })),
            ...workers.filter((w: any) => w.latestLocation || w.coordinate).map((w: any) => ({
              id: w.userId || w.id,
              lat: w.latestLocation?.latitude ?? w.coordinate?.latitude,
              lng: w.latestLocation?.longitude ?? w.coordinate?.longitude,
              label: w.fullName || w.username || 'worker',
            })),
          ].filter((m: any) => m.lat != null && m.lng != null)}
        />
      </div>
      <div className="panel">
        <h3>Samples</h3>
        <table className="table" aria-label="Samples table">
          <thead>
            <tr><th>Sample</th><th>Status</th><th>Holder</th><th>Stale</th><th></th></tr>
          </thead>
          <tbody>
            {samples.length === 0 && <tr><td colSpan={5} className="empty">No samples</td></tr>}
            {samples.map((s: any) => (
              <tr key={s.sampleId || s.id}>
                <td>{s.sampleId || s.id}</td>
                <td>{s.status}</td>
                <td>{s.currentHolderId || s.holderId || '—'}</td>
                <td>{s.locationStale || s.stale ? 'stale' : 'fresh'}</td>
                <td><button type="button" className="secondary" onClick={() => onOpenSample(s.sampleId || s.id)}>Open</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

function AuditView({ audit, query, setQuery, onSearch }: any) {
  const entries = audit?.entries || audit?.items || audit?.results || (Array.isArray(audit) ? audit : [])
  return (
    <div className="panel">
      <h2>Audit trail</h2>
      <form
        aria-label="Search audit trail"
        onSubmit={e => { e.preventDefault(); onSearch() }}
        style={{ display: 'flex', gap: 8, marginBottom: 12 }}
      >
        <input
          aria-label="Audit search"
          placeholder="Search actions, entities…"
          value={query}
          onChange={e => setQuery(e.target.value)}
          style={{ flex: 1, marginBottom: 0 }}
        />
        <button type="submit">Search</button>
      </form>
      <table className="table" aria-label="Audit results">
        <thead>
          <tr><th>Time</th><th>Actor</th><th>Role</th><th>Action</th><th>Entity</th><th>Outcome</th></tr>
        </thead>
        <tbody>
          {entries.length === 0 && <tr><td colSpan={6} className="empty">No audit entries</td></tr>}
          {entries.map((e: any, i: number) => (
            <tr key={e.auditId || e.audit_id || i}>
              <td>{e.occurredAt || e.createdAt || e.time}</td>
              <td>{e.actorId || e.actor_id}</td>
              <td>{e.role || e.actorRole}</td>
              <td>{e.action}</td>
              <td>{e.entityType || e.entity_type} {e.entityId || e.entity_id}</td>
              <td>{e.success === false ? 'fail' : 'ok'}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

function CapacityView({ ops, bootstrap, onSaved, onError }: any) {
  const locations = ops?.locations || bootstrap?.locations || []
  const [resourceId, setResourceId] = useState('')
  const [units, setUnits] = useState('100')
  const [cooled, setCooled] = useState('50')

  useEffect(() => {
    if (!resourceId && locations[0]) setResourceId(locations[0].locationId || locations[0].id)
  }, [locations])

  async function save(e: React.FormEvent) {
    e.preventDefault()
    try {
      await OpsAPI.capacity({
        resourceId,
        capacityUnits: parseInt(units, 10),
        cooledCapacityUnits: parseInt(cooled, 10),
      })
      onSaved()
    } catch (err: any) {
      onError(err.message)
    }
  }

  const selected = locations.find((l: any) => (l.locationId || l.id) === resourceId)
  const cap = selected?.capacity || selected

  return (
    <div className="panel">
      <h2>Capacity</h2>
      <p className="muted">Configure regular and cooled capacity for your node or laboratory.</p>
      {cap && (
        <div className="chips" style={{ marginBottom: 12 }} aria-label="Current capacity">
          <span className="chip">Regular: {cap.capacityUnits ?? cap.capacity_units ?? '—'} (avail {cap.availableUnits ?? '—'})</span>
          <span className="chip">Cooled: {cap.cooledCapacityUnits ?? cap.cooled_capacity_units ?? '—'} (avail {cap.cooledAvailableUnits ?? '—'})</span>
        </div>
      )}
      <form aria-label="Configure capacity" onSubmit={save}>
        <label htmlFor="resource">Resource</label>
        <select id="resource" value={resourceId} onChange={e => setResourceId(e.target.value)}>
          {locations.map((l: any) => (
            <option key={l.locationId || l.id} value={l.locationId || l.id}>{l.name || l.locationId || l.id}</option>
          ))}
        </select>
        <label htmlFor="units">Regular capacity units</label>
        <input id="units" value={units} onChange={e => setUnits(e.target.value)} />
        <label htmlFor="cooled">Cooled capacity units</label>
        <input id="cooled" value={cooled} onChange={e => setCooled(e.target.value)} />
        <button type="submit">Save capacity</button>
      </form>
    </div>
  )
}

function LocationView({ work, onSaved, onError }: any) {
  const assignments = useMemo(() => {
    const out: any[] = []
    const walk = (x: any) => {
      if (!x) return
      if (Array.isArray(x)) x.forEach(walk)
      else if (typeof x === 'object') {
        if (x.assignmentId) out.push(x)
        Object.values(x).forEach(walk)
      }
    }
    walk(work)
    return out
  }, [work])
  const [assignmentId, setAssignmentId] = useState('')
  const [lat, setLat] = useState('51.5074')
  const [lng, setLng] = useState('-0.1278')
  const [seq, setSeq] = useState('1')

  useEffect(() => {
    if (!assignmentId && assignments[0]) setAssignmentId(assignments[0].assignmentId)
  }, [assignments])

  async function save(e: React.FormEvent) {
    e.preventDefault()
    try {
      await OpsAPI.location({
        assignmentId,
        coordinate: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
        sequence: parseInt(seq, 10),
        recordedAt: nowIso(),
      })
      onSaved()
      setSeq(String(parseInt(seq, 10) + 1))
    } catch (err: any) {
      onError(err.message)
    }
  }

  return (
    <div className="panel">
      <h2>Record location</h2>
      <form aria-label="Record worker location" onSubmit={save}>
        <label htmlFor="asg">Assignment</label>
        <select id="asg" value={assignmentId} onChange={e => setAssignmentId(e.target.value)} required>
          <option value="">Select assignment…</option>
          {assignments.map((a: any) => (
            <option key={a.assignmentId} value={a.assignmentId}>{a.assignmentId} ({a.status || a.assignmentType || 'work'})</option>
          ))}
        </select>
        <div className="grid-2">
          <div>
            <label htmlFor="wlat">Latitude</label>
            <input id="wlat" value={lat} onChange={e => setLat(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="wlng">Longitude</label>
            <input id="wlng" value={lng} onChange={e => setLng(e.target.value)} required />
          </div>
        </div>
        <label htmlFor="seq">Sequence</label>
        <input id="seq" value={seq} onChange={e => setSeq(e.target.value)} required />
        <button type="submit">Record location</button>
      </form>
    </div>
  )
}

function AdminView({ bootstrap, ops, onRefresh, onError, onNotice }: any) {
  return (
    <div className="stack">
      <div className="panel">
        <h2>Administrator</h2>
        <p className="muted">Manage network configuration via API. Sample types and bootstrap data are shown below.</p>
        <button type="button" className="secondary" onClick={onRefresh}>Refresh bootstrap</button>
      </div>
      <div className="panel">
        <h3>Sample types</h3>
        <ul>
          {(bootstrap?.sampleTypes || ops?.sampleTypes || []).map((t: any) => (
            <li key={t.sampleTypeId || t.id}>{t.name} — {t.containerType || t.container_type}</li>
          ))}
        </ul>
      </div>
      <div className="panel">
        <h3>Locations</h3>
        <ul>
          {(ops?.locations || []).map((l: any) => (
            <li key={l.locationId || l.id}>{l.name} ({l.active ? 'active' : 'inactive'})</li>
          ))}
        </ul>
      </div>
    </div>
  )
}

