import React, { useEffect, useRef } from 'react'
import maplibregl from 'maplibre-gl'
import { Protocol } from 'pmtiles'

type Marker = { id: string; lat: number; lng: number; label?: string }

let protocolRegistered = false

export default function MapView({ markers = [] as Marker[] }) {
  const ref = useRef<HTMLDivElement>(null)
  const mapRef = useRef<maplibregl.Map | null>(null)
  const markersRef = useRef<maplibregl.Marker[]>([])

  useEffect(() => {
    if (!ref.current || mapRef.current) return

    if (!protocolRegistered) {
      const protocol = new Protocol()
      maplibregl.addProtocol('pmtiles', protocol.tile)
      protocolRegistered = true
    }

    const styleUrl = '/map-assets/style.json'
    const map = new maplibregl.Map({
      container: ref.current,
      style: styleUrl,
      center: [-0.12, 51.50],
      zoom: 10,
      attributionControl: true,
    })
    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'top-right')
    mapRef.current = map

    map.on('error', () => {
      // fall back to blank style if local tiles missing
      if (!map.isStyleLoaded()) {
        map.setStyle({
          version: 8,
          sources: {},
          layers: [{ id: 'bg', type: 'background', paint: { 'background-color': '#e2e8f0' } }],
        } as any)
      }
    })

    return () => {
      map.remove()
      mapRef.current = null
    }
  }, [])

  useEffect(() => {
    const map = mapRef.current
    if (!map) return
    markersRef.current.forEach(m => m.remove())
    markersRef.current = []
    const bounds = new maplibregl.LngLatBounds()
    let has = false
    for (const m of markers) {
      if (m.lat == null || m.lng == null || Number.isNaN(m.lat) || Number.isNaN(m.lng)) continue
      const el = document.createElement('div')
      el.style.width = '14px'
      el.style.height = '14px'
      el.style.borderRadius = '50%'
      el.style.background = '#0f766e'
      el.style.border = '2px solid white'
      el.style.boxShadow = '0 1px 4px rgba(0,0,0,0.35)'
      el.title = m.label || m.id
      const marker = new maplibregl.Marker({ element: el }).setLngLat([m.lng, m.lat]).addTo(map)
      if (m.label) {
        marker.setPopup(new maplibregl.Popup({ offset: 12 }).setText(m.label))
      }
      markersRef.current.push(marker)
      bounds.extend([m.lng, m.lat])
      has = true
    }
    if (has) {
      if (markers.length === 1) {
        map.easeTo({ center: [markers[0].lng, markers[0].lat], zoom: 11 })
      } else {
        map.fitBounds(bounds, { padding: 40, maxZoom: 12 })
      }
    }
  }, [markers])

  return <div className="map-box" ref={ref} role="img" aria-label="Network map" />
}

