			VALUES ($1::uuid,$2::uuid,$3::uuid,$4,'transport',$5,'offered',$6::uuid,$7::uuid)`,
			aid, journeyID, sampleID, models.MustJSON([]string{sampleID}), seq, fromID, toID)

		if firstTransport == "" {
			firstTransport = aid
		} else if i < len(nodes)-2 {
			middleTransport = aid
		}
		if i == len(nodes)-2 {
			finalTransport = aid
		}

		fromLoc := locMap[fromID]
		toLoc := locMap[toID]
		// handoff stop at from (except first)
		if i > 0 || alreadySealed {
