	s.offerAssignment(labAid, "laboratory", sampleID, st)
	s.reserveCapacity("location", labID, sampleID, journeyID, 1, st.RequiresCooled)

	cost := svc.Path.CostUnits
	capUsed := 1
	capAvail := lab.CapacityUnits - lab.ReservedUnits - 1
	if capAvail < 0 {
		capAvail = 0
	}
