		journeyID, routeMode, est, cost, capUsed, capAvail,
		models.MustJSON([]string{sampleID}), models.MustJSON(stops), models.MustJSON(legs),
		nullUUID(collectionAssignment), models.MustJSON(collectionAssignmentIDs),
		models.MustJSON(nodeAssignmentIDs), models.MustJSON(labAssignmentIDs),
		nullUUID(firstTransport), nullUUID(middleTransport), nullUUID(finalTransport), valid,
	)
	if err != nil {
		return "", nil, err
	}
	_, _ = s.DB.SQL.Exec(`UPDATE samples SET active_journey_id=$1::uuid, target_laboratory_id=$2::uuid, updated_at=NOW() WHERE id=$3::uuid`,
		journeyID, labID, sampleID)
	return journeyID, assignmentIDs, nil
}

