func (s *Service) ReadSampleLifecycle(sampleID string, sess *SessionInfo) (map[string]interface{}, error) {
        sm, err := s.loadSample(sampleID)
        if err != nil {
                return nil, err
        }
        if sess.ActiveRole == models.RoleRequester && sm.RequesterID != sess.UserID {
                return nil, Err(403, "forbidden", "not your sample")
        }
        timeline := s.GetTimeline(sampleID)
        locStale := true
        out := map[string]interface{}{
                "sampleId":                  sm.ID,
                "status":                    sm.Status,
                "sealed":                    sm.Sealed,
                "completedLegIds":           sm.CompletedLegIDs,
                "activeReplacementPlanIds":  sm.ActiveReplacementPlanIDs,
                "timeline":                  timeline,
                "locationStale":             locStale,
        }
        if sm.ActiveJourneyID.Valid {
                out["activeJourneyId"] = sm.ActiveJourneyID.String
        }
        if sm.CurrentHolderID.Valid {
                out["currentHolderId"] = sm.CurrentHolderID.String
        }
        if sm.ReceivedLabID.Valid {
                out["receivedLaboratoryId"] = sm.ReceivedLabID.String
        }
        if len(sm.Exception) > 0 && string(sm.Exception) != "null" {
                var exc interface{}
                _ = json.Unmarshal(sm.Exception, &exc)
                out["exception"] = exc
        }
        if sm.PendingHandoffID.Valid {
                out["pendingHandoffId"] = sm.PendingHandoffID.String
                var h map[string]interface{}
                var hid, sid, rid, status string
                var sc, rc bool
                err := s.DB.SQL.QueryRow(`SELECT id::text, sender_id::text, receiver_id::text, status, sender_confirmed, receiver_confirmed FROM handoffs WHERE id=$1::uuid`, sm.PendingHandoffID.String).
                        Scan(&hid, &sid, &rid, &status, &sc, &rc)
                if err == nil {
                        h = map[string]interface{}{"handoffId": hid, "senderId": sid, "receiverId": rid, "status": status, "senderConfirmed": sc, "receiverConfirmed": rc}
                        out["pendingHandoff"] = h
                }
        }
        if sm.LatestLat.Valid && sm.LatestLng.Valid {
                out["latestLocation"] = models.Coordinate{Latitude: sm.LatestLat.Float64, Longitude: sm.LatestLng.Float64}
                if sm.LocationRecordedAt.Valid {
                        t := sm.LocationRecordedAt.Time.UTC()
                        out["locationRecordedAt"] = t
                        out["locationStale"] = isStale(&t, s.Cfg.LocationStaleSec)
                }
        }
        return out, nil
}

func (s *Service) CollectAndSeal(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
        sampleID, _ := req["sampleId"].(string)
        assignmentID, _ := req["assignmentId"].(string)
        container, _ := req["containerType"].(string)
        temp := toFloat(req["observedTemperatureC"])
        collectedAt, err := parseTimeAny(req["collectedAt"])
        if err != nil {
                return nil, Err(400, "invalid_time", "invalid collectedAt")
        }
        idem, _ := req["idempotencyKey"].(string)

        st, resp, err := s.Idempotent(actorID, idem, "collect_and_seal", func() (int, interface{}, error) {
                sm, err := s.loadSample(sampleID)
                if err != nil {
                        return 0, nil, err
                }
                var aStatus, aType string
                var workerID sql.NullString
                err = s.DB.SQL.QueryRow(`SELECT status, assignment_type, worker_id::text FROM assignments WHERE id=$1::uuid`, assignmentID).
                        Scan(&aStatus, &aType, &workerID)
                if err == sql.ErrNoRows {
                        return 0, nil, Err(404, "not_found", "assignment not found")
                }
                if err != nil {
                        return 0, nil, err
                }
                if aType != "collection" {
                        return 0, nil, Err(409, "invalid_assignment", "not a collection assignment")
                }
                if aStatus != "accepted" && aStatus != "in_progress" {
                        return 0, nil, Err(409, "assignment_not_ready", "assignment not accepted")
                }
                if !workerID.Valid || workerID.String != actorID {
                        return 0, nil, Err(403, "ineligible_worker", "not assigned worker")
                }
                // collection window
                if collectedAt.Before(sm.Earliest) || collectedAt.After(sm.Latest) {
                        return 0, nil, Err(409, "outside_collection_window", "collection outside window")
                }
                compliant := temp >= sm.TempMin && temp <= sm.TempMax
                if container != "" && sm.ContainerType != "" && container != sm.ContainerType {
                        // soft check - still allow but mark non-compliant if wildly different? keep compliant based on temp mainly
                }
                status := "sealed"
                if !compliant {
                        exc, _ := json.Marshal(map[string]interface{}{"reason": "handling_noncompliant", "temperature": temp, "container": container})
                        _, _ = s.DB.SQL.Exec(`UPDATE samples SET exception=$1 WHERE id=$2::uuid`, exc, sampleID)
                        status = "exception"
                }
                _, err = s.DB.SQL.Exec(`
                        UPDATE samples SET sealed=TRUE, sealed_at=$1, status=$2, current_holder_id=$3::uuid,
                                latest_lat=$4, latest_lng=$5, location_recorded_at=$1, updated_at=NOW()
                        WHERE id=$6::uuid`, collectedAt, status, actorID, sm.OriginLat, sm.OriginLng, sampleID)
                if err != nil {
                        return 0, nil, err
                }
                _, _ = s.DB.SQL.Exec(`UPDATE assignments SET status='completed', progress_status='completed', completed_at=$1, updated_at=NOW() WHERE id=$2::uuid`, collectedAt, assignmentID)
                // mark completed leg
                completed := append(sm.CompletedLegIDs, assignmentID)
                _, _ = s.DB.SQL.Exec(`UPDATE samples SET completed_leg_ids=$1 WHERE id=$2::uuid`, models.MustJSON(completed), sampleID)

                s.AddTimeline(sampleID, actorID, role, "sample.collected_sealed", "sample", sampleID, true,
                        map[string]interface{}{"assignmentId": assignmentID, "compliant": compliant})
                _ = s.Audit(actorID, role, "sample.collect_and_seal", "sample", sampleID, true, req)
                s.Emit("sample.sealed", "sample", sampleID, []string{"*"}, map[string]interface{}{"sampleId": sampleID, "status": status})

                // activate next transport offers already exist
                return 201, map[string]interface{}{
                        "sampleId":          sampleID,
                        "status":            "sealed",
                        "currentHolderId":   actorID,
                        "sealedAt":          collectedAt.UTC(),
                        "handlingCompliant": compliant,
                }, nil
        })
        if err != nil {
                return nil, err
        }
        _ = st
        return asMap(resp), nil
}

