const TOKEN_KEY = 'lab_session_token'
const USER_KEY = 'lab_session_user'

export type SessionUser = {
  sessionToken: string
  userId: string
  roles: string[]
  activeRole: string
  username?: string
  fullName?: string
}

export function getToken(): string | null {
  return localStorage.getItem(TOKEN_KEY)
}

export function getStoredUser(): SessionUser | null {
  const raw = localStorage.getItem(USER_KEY)
  if (!raw) return null
  try { return JSON.parse(raw) } catch { return null }
}

export function saveSession(u: SessionUser) {
  localStorage.setItem(TOKEN_KEY, u.sessionToken)
  localStorage.setItem(USER_KEY, JSON.stringify(u))
}

export function clearSession() {
  localStorage.removeItem(TOKEN_KEY)
  localStorage.removeItem(USER_KEY)
}

export class ApiError extends Error {
  status: number
  code: string
  constructor(status: number, code: string, message: string) {
    super(message)
    this.status = status
    this.code = code
  }
}

export async function api<T = any>(path: string, opts: RequestInit = {}): Promise<T> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...(opts.headers as any || {}),
  }
  const token = getToken()
  if (token) headers['Authorization'] = `Bearer ${token}`
  const res = await fetch(path.startsWith('/api') ? path : `/api${path}`, {
    ...opts,
    headers,
  })
  const text = await res.text()
  let body: any = null
  try { body = text ? JSON.parse(text) : null } catch { body = { error: text } }
  if (!res.ok) {
    throw new ApiError(res.status, body?.code || 'error', body?.error || body?.message || res.statusText)
  }
  return body?.data !== undefined ? body.data : body
}

