func (s *Service) RecordLabException(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
        sampleID, _ := req["sampleId"].(string)
        reason, _ := req["reason"].(string)
        idem, _ := req["idempotencyKey"].(string)
        st, resp, err := s.Idempotent(actorID, idem, "record_laboratory_exception", func() (int, interface{}, error) {
                exc, _ := json.Marshal(map[string]interface{}{"reason": reason, "recordedBy": actorID, "at": nowUTC()})
                res, err := s.DB.SQL.Exec(`UPDATE samples SET status='exception', exception=$1, updated_at=NOW() WHERE id=$2::uuid`, exc, sampleID)
                if err != nil {
                        return 0, nil, err
                }
                n, _ := res.RowsAffected()
                if n == 0 {
                        return 0, nil, Err(404, "not_found", "sample not found")
                }
                s.AddTimeline(sampleID, actorID, role, "sample.lab_exception", "sample", sampleID, true, map[string]interface{}{"reason": reason})
                _ = s.Audit(actorID, role, "sample.lab_exception", "sample", sampleID, true, req)
                return 201, map[string]interface{}{"sampleId": sampleID, "status": "exception", "reason": reason}, nil
        })
        if err != nil {
                return nil, err
        }
        _ = st
        return asMap(resp), nil
}

func (s *Service) RecordHandlingCheckpoint(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
        sampleID, _ := req["sampleId"].(string)
        assignmentID, _ := req["assignmentId"].(string)
        locationID, _ := req["locationId"].(string)
        container, _ := req["containerType"].(string)
        temp := toFloat(req["observedTemperatureC"])
        recordedAt, err := parseTimeAny(req["recordedAt"])
        if err != nil {
                return nil, Err(400, "invalid_time", "invalid recordedAt")
        }
        idem, _ := req["idempotencyKey"].(string)
        st, resp, err := s.Idempotent(actorID, idem, "record_handling_checkpoint", func() (int, interface{}, error) {
                sm, err := s.loadSample(sampleID)
                if err != nil {
                        return 0, nil, err
                }
                if !sm.CurrentHolderID.Valid || sm.CurrentHolderID.String != actorID {
                        return 0, nil, Err(409, "custody_required", "not current holder")
                }
                compliant := temp >= sm.TempMin && temp <= sm.TempMax
                if sm.ContainerType != "" && container != "" && container != sm.ContainerType {
                        compliant = false
                }
                cid := uuid.New().String()
                _, err = s.DB.SQL.Exec(`
                        INSERT INTO handling_checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_at, recorded_by)
                        VALUES ($1::uuid,$2::uuid,$3::uuid,$4,$5,$6,$7,$8,$9::uuid)`,
                        cid, sampleID, assignmentID, nullUUID(locationID), container, temp, compliant, recordedAt, actorID)
                if err != nil {
                        return 0, nil, err
                }
                status := sm.Status
                if !compliant {
                        exc, _ := json.Marshal(map[string]interface{}{"reason": "handling_checkpoint_failed", "temperature": temp, "container": container})
                        _, _ = s.DB.SQL.Exec(`UPDATE samples SET exception=$1, status='exception', updated_at=NOW() WHERE id=$2::uuid`, exc, sampleID)
                        status = "exception"
                }
                s.AddTimeline(sampleID, actorID, role, "handling.checkpoint", "sample", sampleID, true,
                        map[string]interface{}{"compliant": compliant, "checkpointId": cid})
                _ = s.Audit(actorID, role, "handling.checkpoint", "sample", sampleID, true, req)
                return 201, map[string]interface{}{
                        "checkpointId": cid, "sampleId": sampleID, "compliant": compliant, "sampleStatus": status,
                }, nil
        })
        if err != nil {
                return nil, err
        }
        _ = st
        return asMap(resp), nil
}

func (s *Service) RecordWorkerLocation(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
        assignmentID, _ := req["assignmentId"].(string)
        coord, err := coordFrom(req["coordinate"])
        if err != nil {
                return nil, err
        }
        seq := toInt(req["sequence"])
        recordedAt, err := parseTimeAny(req["recordedAt"])
        if err != nil {
                return nil, Err(400, "invalid_time", "invalid recordedAt")
        }
        var curSeq int
        _ = s.DB.SQL.QueryRow(`SELECT location_seq FROM users WHERE id=$1::uuid`, actorID).Scan(&curSeq)
        if seq <= curSeq {
                // ignore stale but return success with current
                return map[string]interface{}{
                        "assignmentId": assignmentID,
                        "coordinate":   coord,
                        "sequence":     seq,
                        "recordedAt":   recordedAt.UTC(),
                }, nil
        }
        _, _ = s.DB.SQL.Exec(`
                UPDATE users SET latest_lat=$1, latest_lng=$2, location_recorded_at=$3, location_seq=$4, updated_at=NOW()
                WHERE id=$5::uuid`, coord.Latitude, coord.Longitude, recordedAt, seq, actorID)
        _, _ = s.DB.SQL.Exec(`
                INSERT INTO worker_locations (worker_id, assignment_id, latitude, longitude, sequence, recorded_at)
                VALUES ($1::uuid,$2::uuid,$3,$4,$5,$6)`, actorID, nullUUID(assignmentID), coord.Latitude, coord.Longitude, seq, recordedAt)
        // update sample if holding
        _, _ = s.DB.SQL.Exec(`
                UPDATE samples SET latest_lat=$1, latest_lng=$2, location_recorded_at=$3, updated_at=NOW()
                WHERE current_holder_id=$4::uuid AND status NOT IN ('received','cancelled')`,
                coord.Latitude, coord.Longitude, recordedAt, actorID)
        _ = s.Audit(actorID, role, "worker.location", "worker", actorID, true, req)
        return map[string]interface{}{
                "assignmentId": assignmentID,
                "coordinate":   coord,
                "sequence":     seq,
                "recordedAt":   recordedAt.UTC(),
        }, nil
}

func (s *Service) SetWorkerAvailability(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
        workerID, _ := req["workerId"].(string)
        available := toBool(req["available"], true)
        cap := toInt(req["capacityUnits"])
        if role != models.RoleAdministrator && role != models.RoleDispatcher && workerID != actorID {
                return nil, Err(403, "forbidden", "cannot set other worker availability")
        }
        res, err := s.DB.SQL.Exec(`UPDATE users SET available=$1, capacity_units=$2, updated_at=NOW() WHERE id=$3::uuid`, available, cap, workerID)
        if err != nil {
                return nil, err
        }
        n, _ := res.RowsAffected()
        if n == 0 {
                return nil, Err(404, "not_found", "worker not found")
        }
        _ = s.Audit(actorID, role, "worker.set_availability", "worker", workerID, true, req)
        return map[string]interface{}{"workerId": workerID, "available": available, "capacityUnits": cap}, nil
}

func parseTimeAny(v interface{}) (time.Time, error) {
        if v == nil {
                return time.Time{}, nil
        }
        switch t := v.(type) {
        case string:
                if t == "" {
                        return time.Time{}, nil
                }
                formats := []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05Z", "2006-01-02T15:04:05.000Z", "2006-01-02T15:04:05"}
                for _, f := range formats {
                        if tt, err := time.Parse(f, t); err == nil {
                                return tt.UTC(), nil
                        }
                }
                return time.Time{}, Err(400, "invalid_time", "invalid time")
        case time.Time:
                return t.UTC(), nil
        }
        return time.Time{}, Err(400, "invalid_time", "invalid time")
}

func timePtr(t time.Time) *time.Time { return &t }

func strOr(p *string, d string) string {
        if p == nil {
                return d
        }
        return *p
}

func strOrNull(ns sql.NullString) string {
        if ns.Valid {
                return ns.String
        }
        return ""
}

func asMap(v interface{}) map[string]interface{} {
        if m, ok := v.(map[string]interface{}); ok {
                return m
        }
        b, _ := json.Marshal(v)
        var m map[string]interface{}
        _ = json.Unmarshal(b, &m)
        return m
}
