func (s *Service) UIBootstrap(sess *SessionInfo) (map[string]interface{}, error) {
        roleRequired := sess.ActiveRole == "" && len(sess.Roles) > 1
        if len(sess.Roles) == 1 && sess.ActiveRole == "" {
                sess.ActiveRole = sess.Roles[0]
                _, _ = s.DB.SQL.Exec(`UPDATE sessions SET active_role=$1 WHERE token=$2`, sess.ActiveRole, sess.Token)
                roleRequired = false
        }
        user := map[string]interface{}{
                "userId":                sess.UserID,
                "username":              sess.Username,
                "fullName":              sess.FullName,
                "roles":                 sess.Roles,
                "activeRole":            sess.ActiveRole,
                "roleSelectionRequired": roleRequired,
        }
        // sample types available to all roles for forms
        sampleTypes := []map[string]interface{}{}
        stRows, _ := s.DB.SQL.Query(`
                SELECT id::text, name, qualified_collector_required, required_qualification, container_type,
                        temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed
                FROM sample_types ORDER BY name`)
        if stRows != nil {
                defer stRows.Close()
                for stRows.Next() {
                        var id, name, rq, container string
                        var qcr, cooled, batch bool
                        var tmin, tmax float64
                        var inc []byte
                        if stRows.Scan(&id, &name, &qcr, &rq, &container, &tmin, &tmax, &inc, &cooled, &batch) != nil {
                                continue
                        }
                        sampleTypes = append(sampleTypes, map[string]interface{}{
                                "sampleTypeId": id, "name": name, "qualifiedCollectorRequired": qcr,
                                "requiredQualification": rq, "containerType": container,
                                "temperatureMinC": tmin, "temperatureMaxC": tmax,
                                "incompatibleSampleTypes": models.ParseStringSlice(inc),
                                "requiresCooledRoute": cooled, "batchingAllowed": batch,
                        })
                }
        }
        locations := []map[string]interface{}{}
        lRows, _ := s.DB.SQL.Query(`
                SELECT id::text, name, latitude, longitude, coverage_km, handling_minutes, active,
                        fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory,
                        capacity_units, cooled_capacity_units, reserved_units, cooled_reserved_units
                FROM locations ORDER BY name`)
        if lRows != nil {
                defer lRows.Close()
                for lRows.Next() {
                        var id, name string
                        var lat, lng, cov float64
                        var handling, cap, ccap, res, cres int
                        var active, fcp, ftp, fhub, flab bool
                        if lRows.Scan(&id, &name, &lat, &lng, &cov, &handling, &active, &fcp, &ftp, &fhub, &flab, &cap, &ccap, &res, &cres) != nil {
                                continue
                        }
                        locations = append(locations, map[string]interface{}{
                                "locationId": id, "name": name,
                                "coordinate": models.Coordinate{Latitude: lat, Longitude: lng},
                                "coverageKm": cov, "handlingMinutes": handling, "active": active,
                                "functions": models.LocationFunctions{CollectionPoint: fcp, TransferPoint: ftp, Hub: fhub, Laboratory: flab},
                                "capacityUnits": cap, "cooledCapacityUnits": ccap,
                                "availableUnits": cap - res, "cooledAvailableUnits": ccap - cres,
                        })
                }
        }

        out := map[string]interface{}{
                "user":        user,
                "serverTime":  nowUTC(),
                "sampleTypes": sampleTypes,
                "locations":   locations,
        }
        if sess.ActiveRole == models.RoleRequester || contains(sess.Roles, models.RoleRequester) {
                samples := []map[string]interface{}{}
                rows, _ := s.DB.SQL.Query(`SELECT id::text, status, delivery_deadline FROM samples WHERE requester_id=$1::uuid ORDER BY created_at DESC LIMIT 50`, sess.UserID)
                if rows != nil {
                        defer rows.Close()
                        for rows.Next() {
                                var id, status string
                                var dl time.Time
                                if rows.Scan(&id, &status, &dl) == nil {
                                        samples = append(samples, map[string]interface{}{"sampleId": id, "status": status, "deliveryDeadline": dl.UTC()})
                                }
                        }
                }
                out["requesterSamples"] = samples
        }
        if isDispatcherLike(sess.ActiveRole) || sess.ActiveRole == models.RoleNodeHandler || sess.ActiveRole == models.RoleLaboratoryTeam {
                ops, err := s.ReadOperationsState(sess, nil)
                if err == nil {
                        out["operations"] = ops
                }
        }
        return out, nil
}

