func (s *Service) UpdateAssignmentProgress(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
        assignmentID, _ := req["assignmentId"].(string)
        status, _ := req["status"].(string)
        occurredAt, err := parseTimeAny(req["occurredAt"])
        if err != nil {
                return nil, Err(400, "invalid_time", "invalid occurredAt")
        }
        idem, _ := req["idempotencyKey"].(string)
        st, resp, err := s.Idempotent(actorID, idem, "update_assignment_progress", func() (int, interface{}, error) {
                var aStatus, aType string
                var workerID, sampleID sql.NullString
                err := s.DB.SQL.QueryRow(`SELECT status, assignment_type, worker_id::text, sample_id::text FROM assignments WHERE id=$1::uuid`, assignmentID).
                        Scan(&aStatus, &aType, &workerID, &sampleID)
                if err == sql.ErrNoRows {
                        return 0, nil, Err(404, "not_found", "assignment not found")
                }
                if err != nil {
                        return 0, nil, err
                }
                if !workerID.Valid || workerID.String != actorID {
                        return 0, nil, Err(403, "ineligible_worker", "not your assignment")
                }
                if aStatus != "accepted" && aStatus != "in_progress" {
                        return 0, nil, Err(409, "assignment_inactive", "assignment not active")
                }
                newStatus := "in_progress"
                if status == "completed" || status == "delivered" {
                        newStatus = "completed"
                }
                _, _ = s.DB.SQL.Exec(`UPDATE assignments SET status=$1, progress_status=$2, updated_at=NOW(), completed_at=CASE WHEN $1='completed' THEN $3 ELSE completed_at END WHERE id=$4::uuid`,
                        newStatus, status, occurredAt, assignmentID)
                sid := ""
                if sampleID.Valid {
                        sid = sampleID.String
                        s.AddTimeline(sid, actorID, role, "assignment.progress", "assignment", assignmentID, true,
                                map[string]interface{}{"status": status})
                        // update sample location from worker
                        var lat, lng sql.NullFloat64
                        _ = s.DB.SQL.QueryRow(`SELECT latest_lat, latest_lng FROM users WHERE id=$1::uuid`, actorID).Scan(&lat, &lng)
                        if lat.Valid {
                                _, _ = s.DB.SQL.Exec(`UPDATE samples SET latest_lat=$1, latest_lng=$2, location_recorded_at=$3, updated_at=NOW() WHERE id=$4::uuid`,
                                        lat.Float64, lng.Float64, occurredAt, sid)
                        }
                        if newStatus == "completed" {
                                var completed []byte
                                _ = s.DB.SQL.QueryRow(`SELECT completed_leg_ids FROM samples WHERE id=$1::uuid`, sid).Scan(&completed)
                                legs := models.ParseStringSlice(completed)
                                if !contains(legs, assignmentID) {
                                        legs = append(legs, assignmentID)
                                        _, _ = s.DB.SQL.Exec(`UPDATE samples SET completed_leg_ids=$1 WHERE id=$2::uuid`, models.MustJSON(legs), sid)
                                }
                        }
                }
                _ = s.Audit(actorID, role, "assignment.progress", "assignment", assignmentID, true, req)
                return 201, map[string]interface{}{"assignmentId": assignmentID, "sampleId": sid, "status": status}, nil
        })
        if err != nil {
                return nil, err
        }
        _ = st
        return asMap(resp), nil
}

func (s *Service) InitiateHandoff(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
        sampleID, _ := req["sampleId"].(string)
        fromA, _ := req["fromAssignmentId"].(string)
        toA, _ := req["toAssignmentId"].(string)
        receiverID, _ := req["receiverId"].(string)
        initiatedAt, err := parseTimeAny(req["initiatedAt"])
        if err != nil {
                return nil, Err(400, "invalid_time", "invalid initiatedAt")
        }
        idem, _ := req["idempotencyKey"].(string)
        st, resp, err := s.Idempotent(actorID, idem, "initiate_handoff", func() (int, interface{}, error) {
                sm, err := s.loadSample(sampleID)
                if err != nil {
                        return 0, nil, err
                }
                if !sm.Sealed {
                        return 0, nil, Err(409, "collection_required", "sample not sealed")
                }
                if !sm.CurrentHolderID.Valid || sm.CurrentHolderID.String != actorID {
                        return 0, nil, Err(409, "custody_required", "you are not the current holder")
                }
                if sm.PendingHandoffID.Valid {
                        // return existing
                        var hid, sid, rid, status string
                        _ = s.DB.SQL.QueryRow(`SELECT id::text, sender_id::text, receiver_id::text, status FROM handoffs WHERE id=$1::uuid`, sm.PendingHandoffID.String).
                                Scan(&hid, &sid, &rid, &status)
                        return 201, map[string]interface{}{
                                "handoffId": hid, "senderId": sid, "receiverId": rid,
                                "currentHolderId": actorID, "status": "pending",
                        }, nil
                }
                hid := uuid.New().String()
                _, err = s.DB.SQL.Exec(`
                        INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at)
                        VALUES ($1::uuid,$2::uuid,$3::uuid,$4::uuid,$5::uuid,$6::uuid,'pending',$7)`,
                        hid, sampleID, fromA, toA, actorID, receiverID, initiatedAt)
                if err != nil {
                        return 0, nil, err
                }
                _, _ = s.DB.SQL.Exec(`UPDATE samples SET pending_handoff_id=$1::uuid, updated_at=NOW() WHERE id=$2::uuid`, hid, sampleID)
                s.AddTimeline(sampleID, actorID, role, "handoff.initiated", "handoff", hid, true,
                        map[string]interface{}{"receiverId": receiverID})
                _ = s.Audit(actorID, role, "handoff.initiate", "handoff", hid, true, req)
                return 201, map[string]interface{}{
                        "handoffId": hid, "senderId": actorID, "receiverId": receiverID,
                        "currentHolderId": actorID, "status": "pending",
                }, nil
        })
        if err != nil {
                return nil, err
        }
        _ = st
        return asMap(resp), nil
}

func (s *Service) ConfirmHandoff(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
        handoffID, _ := req["handoffId"].(string)
        side, _ := req["confirmationSide"].(string)
        confirmedAt, err := parseTimeAny(req["confirmedAt"])
        if err != nil {
                return nil, Err(400, "invalid_time", "invalid confirmedAt")
        }
        idem, _ := req["idempotencyKey"].(string)
        st, resp, err := s.Idempotent(actorID, idem, "confirm_handoff", func() (int, interface{}, error) {
                var sampleID, senderID, receiverID, status string
                var sc, rc bool
                err := s.DB.SQL.QueryRow(`
                        SELECT sample_id::text, sender_id::text, receiver_id::text, status, sender_confirmed, receiver_confirmed
                        FROM handoffs WHERE id=$1::uuid`, handoffID).
                        Scan(&sampleID, &senderID, &receiverID, &status, &sc, &rc)
                if err == sql.ErrNoRows {
                        return 0, nil, Err(404, "not_found", "handoff not found")
                }
                if err != nil {
                        return 0, nil, err
                }
                if status == "confirmed" {
                        var holder sql.NullString
                        _ = s.DB.SQL.QueryRow(`SELECT current_holder_id::text FROM samples WHERE id=$1::uuid`, sampleID).Scan(&holder)
                        return 201, map[string]interface{}{
                                "handoffId": handoffID, "status": "confirmed",
                                "senderConfirmed": true, "receiverConfirmed": true,
                                "currentHolderId": strOrNull(holder),
                        }, nil
                }
                if side == "sender" {
                        if actorID != senderID {
                                return 0, nil, Err(403, "forbidden", "not the sender")
                        }
                        sc = true
                } else if side == "receiver" {
                        if actorID != receiverID {
                                return 0, nil, Err(403, "forbidden", "not the receiver")
                        }
                        rc = true
                } else {
                        return 0, nil, Err(400, "invalid_json", "invalid confirmationSide")
                }
                holder := senderID
                newStatus := "pending"
                if sc && rc {
                        newStatus = "confirmed"
                        holder = receiverID
                        _, _ = s.DB.SQL.Exec(`UPDATE handoffs SET sender_confirmed=$1, receiver_confirmed=$2, status='confirmed', confirmed_at=$3 WHERE id=$4::uuid`,
                                sc, rc, confirmedAt, handoffID)
                        _, _ = s.DB.SQL.Exec(`UPDATE samples SET current_holder_id=$1::uuid, pending_handoff_id=NULL, status='in_transit', updated_at=NOW() WHERE id=$2::uuid`,
                                holder, sampleID)
                        s.AddTimeline(sampleID, actorID, role, "handoff.confirmed", "handoff", handoffID, true,
                                map[string]interface{}{"currentHolderId": holder})
                } else {
                        _, _ = s.DB.SQL.Exec(`UPDATE handoffs SET sender_confirmed=$1, receiver_confirmed=$2 WHERE id=$3::uuid`, sc, rc, handoffID)
                }
                _ = s.Audit(actorID, role, "handoff.confirm", "handoff", handoffID, true, req)
                return 201, map[string]interface{}{
                        "handoffId": handoffID, "status": newStatus,
                        "senderConfirmed": sc, "receiverConfirmed": rc,
                        "currentHolderId": holder,
                }, nil
        })
        if err != nil {
                return nil, err
        }
        _ = st
        return asMap(resp), nil
}

func (s *Service) ConfirmLabReceipt(actorID, role string, req map[string]interface{}) (map[string]interface{}, error) {
        sampleID, _ := req["sampleId"].(string)
        labID, _ := req["laboratoryId"].(string)
        assignmentID, _ := req["assignmentId"].(string)
        receivedAt, err := parseTimeAny(req["receivedAt"])
        if err != nil || receivedAt.IsZero() {
                receivedAt = nowUTC()
