func (s *Service) loadLocations() ([]locRow, error) {
        rows, err := s.DB.SQL.Query(`
                SELECT id::text, name, latitude, longitude, coverage_km, handling_minutes, active,
                        fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory,
                        capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
                FROM locations`)
        if err != nil {
                return nil, err
        }
        defer rows.Close()
        var out []locRow
        for rows.Next() {
                var l locRow
                if err := rows.Scan(&l.ID, &l.Name, &l.Lat, &l.Lng, &l.CoverageKm, &l.HandlingMinutes, &l.Active,
                        &l.CollectionPoint, &l.TransferPoint, &l.Hub, &l.Laboratory,
                        &l.CapacityUnits, &l.ReservedUnits, &l.CooledCap, &l.CooledReserved); err != nil {
                        return nil, err
                }
                out = append(out, l)
        }
        // load acceptances
        arows, err := s.DB.SQL.Query(`SELECT laboratory_id::text, sample_type_id::text FROM laboratory_acceptance WHERE accepts=TRUE`)
        if err == nil {
                defer arows.Close()
                acc := map[string][]string{}
                for arows.Next() {
                        var lid, tid string
                        if arows.Scan(&lid, &tid) == nil {
                                acc[lid] = append(acc[lid], tid)
                        }
                }
                for i := range out {
                        out[i].AcceptedTypes = acc[out[i].ID]
                        if out[i].AcceptedTypes == nil {
                                out[i].AcceptedTypes = []string{}
                        }
                }
        }
        return out, nil
}

func (s *Service) loadConnections() ([]connRow, error) {
