func (s *Service) findNearestCollection(lat, lng float64, locs []locRow) *locRow {
        var best *locRow
        bestD := 1e18
        for i := range locs {
                l := &locs[i]
                if !l.Active || !l.CollectionPoint {
                        continue
                }
                d := haversineKm(lat, lng, l.Lat, l.Lng)
                if d <= l.CoverageKm && d < bestD {
                        bestD = d
                        best = l
                }
        }
        return best
}

func (s *Service) findPath(fromID, toID string, needCooled bool, conns []connRow, locs []locRow) *routePath {
        // Dijkstra on connections
        type edge struct {
                to, connID string
                minutes    int
                cost       float64
                cooled     bool
        }
        adj := map[string][]edge{}
        for _, c := range conns {
                if !c.Active {
