        collectedAt, err := parseTimeAny(req["collectedAt"])
        if err != nil {
                return nil, Err(400, "invalid_time", "invalid collectedAt")
        }
        idem, _ := req["idempotencyKey"].(string)

        st, resp, err := s.Idempotent(actorID, idem, "collect_and_seal", func() (int, interface{}, error) {
