from pathlib import Path

# Ensure LocationFunctions snake_case matches contract
p = Path('/workspace/backend/internal/models/models.go')
t = p.read_text()
t = t.replace(
'''type LocationFunctions struct {
\tCollectionPoint bool `json:"collectionPoint"`
\tTransferPoint   bool `json:"transferPoint"`
\tHub             bool `json:"hub"`
\tLaboratory      bool `json:"laboratory"`
}''',
'''type LocationFunctions struct {
\tCollectionPoint bool `json:"collection_point"`
\tTransferPoint   bool `json:"transfer_point"`
\tHub             bool `json:"hub"`
\tLaboratory      bool `json:"laboratory"`
}''')
p.write_text(t)
print('models functions snake_case ok')

# Patch routing.go with line-based edit
p = Path('/workspace/backend/internal/service/routing.go')
lines = p.read_text().splitlines(True)

start = None
for i, l in enumerate(lines):
    if '// Now create assignments and offer them' in l:
        start = i
        break
if start is None:
    raise SystemExit('start not found')
end = None
for i in range(start, len(lines)):
    if 'UPDATE samples SET active_journey_id' in lines[i]:
        end = i
        break
if end is None:
    raise SystemExit('end not found')
print('replacing lines', start + 1, 'to', end)

new_block = '''\t// Create assignments. Offer collection immediately; delay transport/node/lab until sealed
\t// unless already sealed (pre-sealed registration).
\tasSeq := 1
\tif collectionAssignment != "" {
\t\tfromLoc := svc.CollectionNodeID
\t\tif _, err = s.DB.SQL.Exec(`
\t\t\tINSERT INTO assignments (id, journey_id, sample_id, sample_ids, assignment_type, sequence, status, to_location_id)
\t\t\tVALUES ($1::uuid,$2::uuid,$3::uuid,$4,'collection',$5,'offered',$6::uuid)`,
\t\t\tcollectionAssignment, journeyID, sampleID, models.MustJSON([]string{sampleID}), asSeq, fromLoc); err != nil {
\t\t\treturn "", nil, err
\t\t}
\t\tasSeq++
\t}
\tofferIdx := 0
\tif collectionAssignment != "" {
\t\ts.offerAssignment(collectionAssignment, "collection", sampleID, st)
\t\tofferIdx = 1
\t}
\tactivateRest := alreadySealed
\tfor i := 0; i < len(nodes)-1; i++ {
\t\taid := offers[offerIdx].aid
\t\tfromID := nodes[i]
\t\ttoID := nodes[i+1]
\t\tstatus := "pending"
\t\tif activateRest {
\t\t\tstatus = "offered"
\t\t}
\t\tif _, err = s.DB.SQL.Exec(`
\t\t\tINSERT INTO assignments (id, journey_id, sample_id, sample_ids, assignment_type, sequence, status, from_location_id, to_location_id)
\t\t\tVALUES ($1::uuid,$2::uuid,$3::uuid,$4,'transport',$5,$6,$7::uuid,$8::uuid)`,
\t\t\taid, journeyID, sampleID, models.MustJSON([]string{sampleID}), asSeq, status, fromID, toID); err != nil {
\t\t\treturn "", nil, err
\t\t}
\t\tasSeq++
\t\tif activateRest {
\t\t\ts.offerAssignment(aid, "transport", sampleID, st)
\t\t}
\t\tif i < len(svc.Path.ConnIDs) {
\t\t\ts.reserveCapacity("connection", svc.Path.ConnIDs[i], sampleID, journeyID, 1, st.RequiresCooled)
\t\t}
\t\tofferIdx++
\t}
\tfor i, nid := range nodes {
\t\tif i == 0 || i == len(nodes)-1 {
\t\t\tcontinue
\t\t}
\t\tn := locMap[nid]
\t\tif n.Hub || n.TransferPoint {
\t\t\taid := offers[offerIdx].aid
\t\t\tstatus := "pending"
\t\t\tif activateRest {
\t\t\t\tstatus = "offered"
\t\t\t}
\t\t\tif _, err = s.DB.SQL.Exec(`
\t\t\t\tINSERT INTO assignments (id, journey_id, sample_id, sample_ids, assignment_type, sequence, status, to_location_id)
\t\t\t\tVALUES ($1::uuid,$2::uuid,$3::uuid,$4,'node',$5,$6,$7::uuid)`,
\t\t\t\taid, journeyID, sampleID, models.MustJSON([]string{sampleID}), asSeq, status, nid); err != nil {
\t\t\t\treturn "", nil, err
\t\t\t}
\t\t\tasSeq++
\t\t\tif activateRest {
\t\t\t\ts.offerAssignment(aid, "node", sampleID, st)
\t\t\t}
\t\t\ts.reserveCapacity("location", nid, sampleID, journeyID, 1, st.RequiresCooled)
\t\t\tofferIdx++
\t\t}
\t}
\tlabStatus := "pending"
\tif activateRest {
\t\tlabStatus = "offered"
\t}
\tif _, err = s.DB.SQL.Exec(`
\t\tINSERT INTO assignments (id, journey_id, sample_id, sample_ids, assignment_type, sequence, status, to_location_id)
\t\tVALUES ($1::uuid,$2::uuid,$3::uuid,$4,'laboratory',$5,$6,$7::uuid)`,
\t\tlabAid, journeyID, sampleID, models.MustJSON([]string{sampleID}), asSeq, labStatus, labID); err != nil {
\t\treturn "", nil, err
\t}
\tif activateRest {
\t\ts.offerAssignment(labAid, "laboratory", sampleID, st)
\t}
\ts.reserveCapacity("location", labID, sampleID, journeyID, 1, st.RequiresCooled)

'''
lines = lines[:start] + [new_block] + lines[end:]
text = ''.join(lines)
if 'func (s *Service) activatePendingAssignments' not in text:
    helper = '''
func (s *Service) activatePendingAssignments(sampleID string) {
\trows, err := s.DB.SQL.Query(`
\t\tSELECT id::text, assignment_type FROM assignments
\t\tWHERE sample_id=$1::uuid AND status='pending'
\t\tORDER BY sequence ASC`, sampleID)
\tif err != nil {
\t\treturn
\t}
\tdefer rows.Close()
\tvar st *sampleTypeRow
\tvar typeID string
\t_ = s.DB.SQL.QueryRow(`SELECT sample_type_id::text FROM samples WHERE id=$1::uuid`, sampleID).Scan(&typeID)
\tif typeID != "" {
\t\tst, _ = s.loadSampleType(typeID)
\t}
\tfor rows.Next() {
\t\tvar id, aType string
\t\tif rows.Scan(&id, &aType) != nil {
\t\t\tcontinue
\t\t}
\t\t_, _ = s.DB.SQL.Exec(`UPDATE assignments SET status='offered', updated_at=NOW() WHERE id=$1::uuid`, id)
\t\ts.offerAssignment(id, aType, sampleID, st)
\t}
}

'''
    text = text.replace('func (s *Service) offerAssignment(', helper + 'func (s *Service) offerAssignment(', 1)
p.write_text(text)
print('routing patched')

# samples collect activate
p = Path('/workspace/backend/internal/service/samples.go')
t = p.read_text()
if 's.activatePendingAssignments(sampleID)' not in t:
    t = t.replace(
        '// activate next transport offers already exist',
        '// activate next pending transport/node/lab assignments\n\t\t\ts.activatePendingAssignments(sampleID)'
    )
t = t.replace(
'''\t\t\tcompliant := temp >= sm.TempMin && temp <= sm.TempMax
\t\t\tif container != "" && sm.ContainerType != "" && container != sm.ContainerType {
\t\t\t\t// soft check - still allow but mark non-compliant if wildly different? keep compliant based on temp mainly
\t\t\t}''',
'''\t\t\tcompliant := temp >= sm.TempMin && temp <= sm.TempMax
\t\t\tif container != "" && sm.ContainerType != "" && container != sm.ContainerType {
\t\t\t\tcompliant = false
\t\t\t}''')
p.write_text(t)
print('samples patched, activate present', 'activatePendingAssignments' in t)

