func HashPassword(pw string) (string, error) {
        b, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
        return string(b), err
}

func CheckPassword(hash, pw string) bool {
        return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}

func NewToken() string {
        b := make([]byte, 32)
        _, _ = rand.Read(b)
        return hex.EncodeToString(b)
}

func ExtractBearer(r *http.Request) string {
        h := r.Header.Get("Authorization")
        if h == "" {
                return ""
        }
        parts := strings.SplitN(h, " ", 2)
        if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") {
                return ""
        }
        return strings.TrimSpace(parts[1])
}

// ExtractWSToken reads bearer.<token> from websocket subprotocols.
func ExtractWSToken(protocols []string) string {
        for _, p := range protocols {
                if strings.HasPrefix(p, "bearer.") {
                        enc := strings.TrimPrefix(p, "bearer.")
                        // try raw first
                        if dec, err := base64.RawURLEncoding.DecodeString(enc); err == nil && len(dec) > 0 {
                                return string(dec)
                        }
                        if dec, err := base64.URLEncoding.DecodeString(enc); err == nil && len(dec) > 0 {
                                return string(dec)
                        }
                        return enc
                }
        }
        return ""
}

