export PGDATABASE="${PGDATABASE:-arena}"
export PGDATA="${PGDATA:-/workspace/data/pg}"
export DATABASE_URL="${DATABASE_URL:-postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable}"
export MONGODB_URI="${MONGODB_URI:-mongodb://127.0.0.1:27017}"
export MONGODB_DB="${MONGODB_DB:-lablogistics}"

mkdir -p /workspace/data/pg_log /tmp

ensure_postgres() {
  if pg_isready -h "$PGHOST" -p "$PGPORT" -U "$PGUSER" >/dev/null 2>&1; then
    return 0
  fi
  if [ ! -f "$PGDATA/PG_VERSION" ]; then
    mkdir -p "$PGDATA"
    initdb -D "$PGDATA" --auth=trust --username=arena
  fi
  cat > "$PGDATA/postgresql.conf" <<EOF
listen_addresses = '127.0.0.1'
port = 5432
unix_socket_directories = '/tmp'
max_connections = 50
shared_buffers = 64MB
logging_collector = off
log_destination = 'stderr'
EOF
  cat > "$PGDATA/pg_hba.conf" <<EOF
local all all trust
host all all 127.0.0.1/32 trust
host all all ::1/128 trust
EOF
  rm -f /tmp/.s.PGSQL.5432 /tmp/.s.PGSQL.5432.lock
  pg_ctl -D "$PGDATA" -l /workspace/data/pg_log/pg.log -o "-k /tmp -p 5432 -h 127.0.0.1" start || true
  for i in $(seq 1 30); do
    if pg_isready -h "$PGHOST" -p "$PGPORT" -U "$PGUSER" >/dev/null 2>&1; then
      break
    fi
    sleep 0.5
  done
  createdb -h "$PGHOST" -U "$PGUSER" "$PGDATABASE" 2>/dev/null || true
}

echo "[reset] ensuring PostgreSQL..."
ensure_postgres

echo "[reset] wiping PostgreSQL schema..."
psql -h "$PGHOST" -U "$PGUSER" -d "$PGDATABASE" -v ON_ERROR_STOP=1 <<'SQL'
DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;
GRANT ALL ON SCHEMA public TO arena;
GRANT ALL ON SCHEMA public TO public;
SQL

echo "[reset] applying schema.sql..."
psql -h "$PGHOST" -U "$PGUSER" -d "$PGDATABASE" -v ON_ERROR_STOP=1 -f /workspace/backend/internal/db/schema.sql

echo "[reset] materializing MongoDB collections and indexes..."
mongosh --quiet --eval '
db = db.getSiblingDB("lablogistics");
try { db.audit_log.drop(); } catch (e) {}
try { db.events.drop(); } catch (e) {}
try { db.serviceability_snapshots.drop(); } catch (e) {}
try { db.idempotency.drop(); } catch (e) {}
db.createCollection("audit_log");
db.createCollection("events");
db.createCollection("serviceability_snapshots");
db.createCollection("idempotency");
db.audit_log.createIndex({ occurredAt: -1 });
db.audit_log.createIndex({ actorId: 1, occurredAt: -1 });
db.audit_log.createIndex({ entityType: 1, entityId: 1, occurredAt: -1 });
db.audit_log.createIndex({ action: 1, occurredAt: -1 });
db.audit_log.createIndex({ role: 1, occurredAt: -1 });
db.events.createIndex({ id: 1 }, { unique: true });
db.events.createIndex({ createdAt: -1 });
db.serviceability_snapshots.createIndex({ version: -1 }, { unique: true });
db.serviceability_snapshots.createIndex({ publishedAt: -1 });
db.idempotency.createIndex({ key: 1 }, { unique: true });
db.idempotency.createIndex({ createdAt: 1 }, { expireAfterSeconds: 86400 });
print("mongo ready");
' "$MONGODB_URI"

echo "[reset] done — application left stopped"
smoke_test.py
openapi.contract.json  ui.contract.json

