from pathlib import Path

p = Path('/workspace/backend/internal/service/service.go')
t = p.read_text()

# After EnsureDefaultSampleTypes call in EnsureAdmin, also ensure demo network
if 'EnsureDemoNetwork' not in t:
    t = t.replace(
        'return s.EnsureDefaultSampleTypes()\n}',
        'if err := s.EnsureDefaultSampleTypes(); err != nil {\n\t\treturn err\n\t}\n\treturn s.EnsureDemoNetwork()\n}',
        1,
    )

    helper = r'''
// EnsureDemoNetwork seeds a minimal Bangalore collection+lab network when empty.
func (s *Service) EnsureDemoNetwork() error {
	var n int
	_ = s.DB.SQL.QueryRow(`SELECT COUNT(*) FROM locations`).Scan(&n)
	if n > 0 {
		return nil
	}
	var collID, labID string
	err := s.DB.SQL.QueryRow(`
		INSERT INTO locations (name, latitude, longitude, coverage_km, handling_minutes, active,
			fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory,
			capacity_units, cooled_capacity_units)
		VALUES ('Bangalore Collection Hub', 12.9716, 77.5946, 5, 10, TRUE,
			TRUE, TRUE, TRUE, FALSE, 100, 50)
		RETURNING id::text`).Scan(&collID)
	if err != nil {
		return err
	}
	err = s.DB.SQL.QueryRow(`
		INSERT INTO locations (name, latitude, longitude, coverage_km, handling_minutes, active,
			fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory,
			capacity_units, cooled_capacity_units)
		VALUES ('Bangalore Central Lab', 12.9780, 77.6100, 5, 15, TRUE,
			FALSE, TRUE, FALSE, TRUE, 200, 80)
		RETURNING id::text`).Scan(&labID)
	if err != nil {
		return err
	}
	_, err = s.DB.SQL.Exec(`
		INSERT INTO connections (from_location_id, to_location_id, travel_minutes, cost_units, cooled, active,
			capacity_units, cooled_capacity_units)
		VALUES ($1::uuid, $2::uuid, 20, 1, TRUE, TRUE, 100, 50)`, collID, labID)
	if err != nil {
		return err
	}
	// reverse connection optional
	_, _ = s.DB.SQL.Exec(`
		INSERT INTO connections (from_location_id, to_location_id, travel_minutes, cost_units, cooled, active,
			capacity_units, cooled_capacity_units)
		VALUES ($1::uuid, $2::uuid, 20, 1, TRUE, TRUE, 100, 50)`, labID, collID)

	// accept all sample types at lab
	rows, err := s.DB.SQL.Query(`SELECT id::text FROM sample_types`)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var tid string
			if rows.Scan(&tid) == nil {
				_, _ = s.DB.SQL.Exec(`
					INSERT INTO laboratory_acceptance (laboratory_id, sample_type_id, accepts)
					VALUES ($1::uuid,$2::uuid,TRUE)
					ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts=TRUE`, labID, tid)
			}
		}
	}
	s.bumpNetwork()
	return s.rebuildServiceability()
}
'''
    # insert before CreateLocation
    marker = 'func (s *Service) CreateLocation('
    if marker not in t:
        raise SystemExit('CreateLocation not found')
    t = t.replace(marker, helper + '\n' + marker, 1)
    p.write_text(t)
    print('seed helper added')
else:
    print('already has EnsureDemoNetwork')

# Fix EnsureAdmin path - check what we have
t = p.read_text()
if 'EnsureDemoNetwork' not in t:
    raise SystemExit('failed to add seed')
print('ok')

